        [HttpGet, HttpPost]
        public Object[] LoadCargoProperties(Int64 pOperationIDForCargo, Int64 pMasterOperationID, string pOrderBy)
        {
            // Creates an instance of your JavaScriptSerializer & Setting the MaxJsonLength to handle the case of large data returned
            int _RowCount = 0;
            CDefaults objCDefaults = new CDefaults();
            objCDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount); //i am sure i ve just one row isa
            COperations objCOperations = new COperations();
            objCOperations.GetListPaging(999999, 1, "WHERE ID=" + pOperationIDForCargo, pOrderBy, out _RowCount);
            CvwOperationContainersAndPackages objCvwOperationContainersAndPackages = new CvwOperationContainersAndPackages();
            COperationContainersAndPackagesPlacedOn objCOperationContainersAndPackagesPlacedOn = new COperationContainersAndPackagesPlacedOn();
            objCOperationContainersAndPackagesPlacedOn.GetList(" WHERE OperationID = " + pOperationIDForCargo);
            CvwPlacedOnDetails cvwPlacedOnDetails = new CvwPlacedOnDetails();

            if (objCOperations.lstCVarOperations[0].MasterOperationID > 0)
            {
                if (new string[] { "SUS", "MR" }.Contains(objCDefaults.lstCVarDefaults[0].UnEditableCompanyName))
                {
                    objCvwOperationContainersAndPackages.GetListPaging(999999, 1, "WHERE ContainerTypeID IS NOT NULL AND OperationID=" + pMasterOperationID + " AND ID NOT IN (SELECT OperationContainersAndPackagesID from OperationContainersAndPackagesPlacedOn where OperationID in (select ID from Operations where MasterOperationID=" + pMasterOperationID + "))", "ContainerNumber", out _RowCount);
                }
                else
                {
                    //objCvwOperationContainersAndPackages.GetListPaging(999999, 1, "WHERE ContainerTypeID IS NOT NULL AND OperationID=" + pMasterOperationID/* + " AND ID NOT IN (SELECT OperationContainersAndPackagesID from OperationContainersAndPackagesPlacedOn)"*/, "ContainerNumber", out _RowCount);
                    objCvwOperationContainersAndPackages.GetListPaging(999999, 1, "WHERE ContainerTypeID IS NOT NULL AND OperationID=" + pMasterOperationID, "ContainerNumber", out _RowCount);
                }
                cvwPlacedOnDetails.GetListPaging(99999, 1, "WHERE operationID=" + pOperationIDForCargo, "ID DESC", out _RowCount);



            }
            CPackageTypes objCPackageTypes = new CPackageTypes();
            objCPackageTypes.GetList("ORDER BY Name");
            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new Object[] {
                serializer. Serialize(objCOperations.lstCVarOperations[0]) //pData[0]
                , serializer.Serialize(objCvwOperationContainersAndPackages.lstCVarvwOperationContainersAndPackages) //pData[1]
                , serializer.Serialize(objCPackageTypes.lstCVarPackageTypes) //pData[2]
                , serializer.Serialize(objCOperationContainersAndPackagesPlacedOn.lstCVarOperationContainersAndPackagesPlacedOn) //pData[3]
                , serializer.Serialize(cvwPlacedOnDetails.lstCVarvwPlacedOnDetails) //pData[4]
            };
        }

        [HttpGet, HttpPost]
        public Object[] LoadReeferDetails(Int64 pOperationID)
        {
            // Creates an instance of your JavaScriptSerializer & Setting the MaxJsonLength to handle the case of large data returned
            int _RowCount = 0;
            CDefaults objCDefaults = new CDefaults();
            objCDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount); //i am sure i ve just one row isa
            COperations objCOperations = new COperations();
            objCOperations.GetListPaging(999999, 1, "WHERE ID=" + pOperationID, "ID", out _RowCount);

            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();

            var FirstContainerData = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "SELECT TOP 1 ID,IsReefer,IsNOR,MinTemp,MaxTemp,Humidity,Ventilation FROM OperationContainersAndPackages WHERE OperationID=" + pOperationID + " ORDER BY ID "
                , typeof(CVarOperationContainersAndPackages)).Cast<CVarOperationContainersAndPackages>().ToList();

            var AllContainersData = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "SELECT ID,ContainerNumber,PurchaseItemID,PackageTypeIDOnContainer,NumberOfPackagesOnContainer,GrossWeightTON,NetWeightTON,DescriptionOfGoods FROM OperationContainersAndPackages WHERE OperationID=" + pOperationID + " ORDER BY ID "
                , typeof(CVarOperationContainersAndPackages)).Cast<CVarOperationContainersAndPackages>().ToList();




            CPackageTypes objCPackageTypes = new CPackageTypes();
            objCPackageTypes.GetList("ORDER BY Name");
            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new Object[] {
                serializer.Serialize(FirstContainerData) //pData[0]
                , serializer.Serialize(AllContainersData) //pData[1]
                , serializer.Serialize(objCPackageTypes.lstCVarPackageTypes) //pData[2]
            };
        }

