            cvwReceivables.GetListPaging(99999, 1, "WHERE operationID = " + MasterOperationId + "AND( BillID =" + pSelectedID + "OR BillID is null ) ", "ID", out _RowCount);
            var HouseReceviabls = cvwReceivables.lstCVarvwReceivables;

            var serializer = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };


            return new object[] {
