        #region GuaranteeLetter
        [HttpGet, HttpPost]
        public Object[] LoadGuaranteeLetterData(Int64 pOperationIDForGuaranteeLetter)
        {
            // Creates an instance of your JavaScriptSerializer & Setting the MaxJsonLength to handle the case of large data returned
            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            int _RowCount = 0;
            CBankAccount objCBankAccount = new CBankAccount();
            CvwOperations objCvwOperations = new CvwOperations();
            objCvwOperations.GetListPaging(99999, 1, "WHERE ID=" + pOperationIDForGuaranteeLetter, "ID DESC", out _RowCount);
            objCBankAccount.GetList("ORDER BY Name");
            return new Object[] {
                serializer.Serialize(objCvwOperations.lstCVarvwOperations[0])
                , serializer.Serialize(objCBankAccount.lstCVarBankAccount)
            };
        }

        [HttpGet, HttpPost]
        public Object[] SaveGuaranteeLetter(Int64 pOperationIDForGuaranteeLetter, string pGuaranteeLetterNumber
            , string pGuaranteeLetterDate, string pGuaranteeLetterAmount, string pSupplierReference, string pPONumber
            , Int32 pBankAccountID, string pGuaranteeLetterNotes)
        {
            string _ReturnedMessage = "";
            string _UpdateClause = "";
            Exception checkException = null;
            COperations objCOperations = new COperations();
            _UpdateClause = " GuaranteeLetterNumber = " + (pGuaranteeLetterNumber == "0" ? " NULL " : "'" + pGuaranteeLetterNumber + "' ") + "\n";
            _UpdateClause += pGuaranteeLetterDate == "0" ? " ,GuaranteeLetterDate = NULL " : (" ,GuaranteeLetterDate = '" + (DateTime.ParseExact(pGuaranteeLetterDate + " 00.00.00.000", "dd/MM/yyyy hh.mm.ss.fff", CultureInfo.InvariantCulture)).ToString("yyyyMMdd") + "'") + "\n";
            _UpdateClause += " , GuaranteeLetterAmount = " + (pGuaranteeLetterAmount == "0" ? " NULL " : "'" + pGuaranteeLetterAmount + "' ") + "\n";
            _UpdateClause += " , BankAccountID = " + (pBankAccountID == 0 ? " NULL " : "'" + pBankAccountID + "' ") + "\n";
            _UpdateClause += " , SupplierReference = " + (pSupplierReference == "0" ? " NULL " : "'" + pSupplierReference + "' ") + "\n";
            _UpdateClause += " , PONumber = " + (pPONumber == "0" ? " NULL " : "'" + pPONumber + "' ") + "\n";
            _UpdateClause += " , GuaranteeLetterNotes = " + (pGuaranteeLetterNotes == "0" ? " NULL " : "N'" + pGuaranteeLetterNotes + "' ") + "\n";
            _UpdateClause += "WHERE ID=" + pOperationIDForGuaranteeLetter + "\n";
            checkException = objCOperations.UpdateList(_UpdateClause);
            if (checkException != null)
                _ReturnedMessage = checkException.Message;
            return new object[] {
                _ReturnedMessage
            };
        }
        #endregion GuaranteeLetter

        [HttpGet, HttpPost]
        public object[] Insert([FromBody] InsertOperationData insertOperationData)
        {
            string _MessageReturned = "";
            bool _result = false;
            int MainCarraigeRoutingTypeID = 30;
            COperations objCOperations = new COperations();
            int _RowCount = 0;
            Int64 OperationID = 0;
            Int64 RoutingID = 0;
            Int32 POrC = 0;
            Int64 OperationContainersAndPackagesID = 0;
            Int64 PayableID = 0;
            Int64 OperationPartners = 0;
            bool foundMasterBls = false;
            var objFoundCOperationsCodes = "";
            var evlMessage = "";
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var CancelledTransportOrderID = 80;
            CvwDefaults objCvwDefaults = new CvwDefaults();
            objCvwDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount); //i am sure i ve just one row isa
            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "TRI")
            {

                if (insertOperationData.pVoyageOrTruckNumber == null || insertOperationData.pVoyageOrTruckNumber == "" || insertOperationData.pVoyageOrTruckNumber == "0")
                {
                    return new object[] { 0, 0, 0, "VoyageOrTruckNumber Is required!" };
                }
                else
                {
                    CRoutings objCRoutingsFound = new CRoutings();
                    objCRoutingsFound.GetList("Where VoyageOrTruckNumber = '" + insertOperationData.pVoyageOrTruckNumber + "'");
                    if (objCRoutingsFound.lstCVarRoutings.Count > 0)
                    {
                        return new object[] { 0, 0, 0, "VoyageOrTruckNumber Must be unique!" };
                    }
                }
            }
            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "EVL" && insertOperationData.pMoveTypeID == "25")
            {

                if (insertOperationData.pVoyageOrTruckNumber == null || insertOperationData.pVoyageOrTruckNumber == "" || insertOperationData.pVoyageOrTruckNumber == "0")
                {
                    return new object[] {0,0,0,
                        "Operation Must Has Voyage OR Truck Number!"
                    };
                }
            }//COperationPartners objCOperationPartnersForTax = new COperationPartners();
            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "EVL" && insertOperationData.pMoveTypeID == "27")
            {

                if (insertOperationData.pMasterBL == null || insertOperationData.pMasterBL == "" || insertOperationData.pMasterBL == "0")
                {
                    return new object[] {0,0,0,
                  "Operation Must Has MasterBL!"
                    };
                }
                else
                {
                    insertOperationData.pAgentID = "1112";
                    COperations objFoundCOperations = new COperations();
                    objFoundCOperations.GetList("Where MasterBL = '" + insertOperationData.pMasterBL + "'");
                    if (objFoundCOperations.lstCVarOperations.Count > 0)
                    {
                        objFoundCOperationsCodes = string.Join(",", objFoundCOperations.lstCVarOperations.Select(x => x.Code).ToList());
                        foundMasterBls = true;
                        evlMessage = "Operations (" + objFoundCOperationsCodes + ") Have the Same MasterBl !";
                    }
                }
            }

            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "PYR")
            {
                CvwInvoices objCvwInvoices = new CvwInvoices();
                CCustomers objCCustomerShipper = new CCustomers();
                objCCustomerShipper.GetList("Where ID = " + insertOperationData.pShipperID);
                CCustomers objCCustomerConsignee = new CCustomers();
                objCCustomerConsignee.GetList("Where ID = " + insertOperationData.pConsigneeID);
                if (objCCustomerShipper.lstCVarCustomers.Count > 0)
                {
                    if (!(objCCustomerShipper.lstCVarCustomers[0].IsMustPay == false))
                    {
                        objCvwInvoices.GetList("WHERE PartnerID in (" + insertOperationData.pShipperID + "," + insertOperationData.pConsigneeID + ") AND InvoiceStatus = 'UnPaid' AND DueDate <'" + DateTime.Now.ToString("yyyy-MM-dd") + "'");
                        if (objCvwInvoices.lstCVarvwInvoices.Count > 0)
                        {
                            return new Object[] { _result, 0, 0, "Shipper Or Consignee Have Unpaid Invoices" };
                        }
                    }
                }
                if (objCCustomerConsignee.lstCVarCustomers.Count > 0)
                {
                    if (!(objCCustomerConsignee.lstCVarCustomers[0].IsMustPay == false))
                    {
                        objCvwInvoices.GetList("WHERE PartnerID in (" + insertOperationData.pShipperID + "," + insertOperationData.pConsigneeID + ") AND InvoiceStatus = 'UnPaid' AND DueDate <'" + DateTime.Now.ToString("yyyy-MM-dd") + "'");
                        if (objCvwInvoices.lstCVarvwInvoices.Count > 0)
                        {
                            return new Object[] { _result, 0, 0, "Shipper Or Consignee Have Unpaid Invoices" };
                        }
                    }
                }


            }
            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "AKS")
            {
                // Here IsMustPay used to store if customer is blacklisted or not
                CCustomers objCCustomerShipper = new CCustomers();
                Exception e11 = objCCustomerShipper.GetList("Where ID = " + insertOperationData.pShipperID);
                CCustomers objCCustomerConsignee = new CCustomers();
                Exception e22 = objCCustomerConsignee.GetList("Where ID = " + insertOperationData.pConsigneeID);

                if (e11 != null || e22 != null)
                {
