        public object CreationMessageToUsers([FromBody] CreationMessageToUsers data)
        {
           var errorMessage = "";
            bool result = true;
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();

            var IsHouseExist = objCCustomizedDBCall.CallStringFunction("select id from Operations where HouseNumber='" + data.pHouseNumber);
            if (IsHouseExist != "")
            {

                try
                {
                    int _RowCount = 0;

                    string connectionString = ConfigurationManager.ConnectionStrings["ConnectionString"].ToString();

                    var IsExist = objCCustomizedDBCall.CallStringFunction(
                        "select id from whatsapp where HouseNumber='" + data.pHouseNumber +
                        "' And PhoneNumber='" + data.pUserPhone + "' And IsStorageInvoice = 1"
                    );

                    string insertQuery = "INSERT INTO WhatsApp (Name, HouseNumber, PhoneNumber , IsStorageInvoice) VALUES (@Name, @HouseNumber, @PhoneNumber ,@IsStorageInvoice)";

                    if (IsExist == "")
                    {
                        using (SqlConnection connection = new SqlConnection(connectionString))
                        using (SqlCommand command = new SqlCommand(insertQuery, connection))
                        {
                            command.Parameters.AddWithValue("@Name", data.pUserName);
                            command.Parameters.AddWithValue("@HouseNumber", data.pHouseNumber);
                            command.Parameters.AddWithValue("@PhoneNumber", data.pUserPhone);
                            command.Parameters.AddWithValue("@IsStorageInvoice", 1);

                            connection.Open();
                            command.ExecuteNonQuery();
                        }
                    }
                    CvwDefaults objCvwDefaults = new CvwDefaults();
                    objCvwDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);
                    List<HouseInfo> Houses = new List<HouseInfo>();

                    if (objCvwDefaults.lstCVarvwDefaults[0].mCompanyLocalName == "CPWORLD EGYPT")
                    {
                        Houses = new List<HouseInfo>()
                    {
                        new HouseInfo { PhoneNumber = "201204822241", UserName = "Ali" }

                    };
                    }
                    else
                    {
                        Houses = new List<HouseInfo>()
                    {
                        new HouseInfo { PhoneNumber = "201202308974", UserName = "Mohamed Adel" },
                        new HouseInfo { PhoneNumber = "201227432592", UserName = "Islam" }
                    };
                    }




                    foreach (var h in Houses)
                    {
                        try
                        {
                            StringBuilder str = new StringBuilder();
                            str.AppendLine("🔈🔈🔈");
                            str.AppendLine($"Hello {h.UserName}");
                            str.AppendLine("السّلام عليكم،");
                            str.AppendLine("نرجو من سيادتكم التكرّم بإصدار فاتورة التخزين الخاصة بالبيانات التالية:");
                            str.AppendLine($"رقم البوليصة : {data.pHouseNumber}");
                            str.AppendLine($" اسم العميل : {data.pUserName}");
                            str.AppendLine($"رقم الموبايل : {data.pUserPhone}");
                            str.AppendLine($"تاريخ انتهاء التخزين المطلوب: {data.pEndStorageDate}");
                            str.AppendLine("برجاء التنفيذ في أسرع وقت، وشكراً لتعاونك.");

                            bool isSent = false;

                            if (objCvwDefaults.lstCVarvwDefaults[0].mCompanyLocalName == "CPWORLD EGYPT")
                            {
                                using (UltraMsg ultraMsg = new UltraMsg("instance120848", "bkw3ccdvdlk2vyyx"))
                                {
                                    isSent = ultraMsg.SendWhatsAppMsg("+" + h.PhoneNumber, str.ToString());
                                }
                            }
                            else
                            {
                                using (UltraMsg ultraMsg = new UltraMsg("instance113161", "hu0rupmzj2y2d744"))
                                {
                                    isSent = ultraMsg.SendWhatsAppMsg("+" + h.PhoneNumber, str.ToString());
                                }
                            }

                            if (!isSent)
                            {
                                result = false;
                                errorMessage += $"Failed to send message to {h.PhoneNumber}\n";
                            }
                        }
                        catch (Exception ex)
                        {
                            result = false;
                            errorMessage += $"Error sending message to {h.PhoneNumber}: {ex.Message}\n";
                        }
                    }
                }
                catch (Exception ex)
                {
                    result = false;
                    errorMessage = "General Error: " + ex.Message;
                }

            }
            else
                result = false;
                return new { result = result, error = errorMessage };
        }
