            if (objCvwDefaults.lstCVarvwDefaults[0].mCompanyLocalName == "CPWORLD EGYPT")
            {
                using (UltraMsg ultraMsg = new UltraMsg("instance120848", "bkw3ccdvdlk2vyyx"))
                {
                    isSent = ultraMsg.SendWhatsAppMsg("+" + pPhoneNumber, pMessage.ToString());
                }
            }
            else
            {
                using (UltraMsg ultraMsg = new UltraMsg("instance113161", "hu0rupmzj2y2d744"))
                {
                    isSent = ultraMsg.SendWhatsAppMsg("+" + pPhoneNumber, pMessage.ToString());
                }
            }

            return isSent;
            //return new { result = result};
        }
        [HttpGet, HttpPost]
        public object AddUserDetails(string pHouseNumber)
        {
            var result = false;
            var USerName = "";
            var UserPhone = "";
            CWhatsApp ObjCWhatsApp = new CWhatsApp();
            ObjCWhatsApp.GetList("where IsStorageInvoice = 1 And HouseNumber='"+ pHouseNumber + "'");
            if (ObjCWhatsApp.lstCVarWhatsApp.Count > 0)
            {
              result = true;
              USerName = ObjCWhatsApp.lstCVarWhatsApp[0].Name;
              UserPhone = ObjCWhatsApp.lstCVarWhatsApp[0].PhoneNumber;
            }
            return new { result = result, USerName = USerName , UserPhone = UserPhone };
        }

