        [HttpGet, HttpPost, AllowAnonymous]

        public object HouseFilterChat([FromBody] HouseFilterChatBody data)
        {
            int _RowCount = 0;
            int _RowCount2 = 0;
            var IsCpWorld = false;
            CvwOperationsForWhatsAPP objCvwOperations = new CvwOperationsForWhatsAPP();
            CvwOperationsForWhatsAPP objCvwOperationsMaster = new CvwOperationsForWhatsAPP();
            objCvwOperations.GetListPaging(10, 1, "Where HouseNumber ='" + data.pHouseNumber + "'", " ID DESC ", out _RowCount);
            CvwDefaults objCvwDefaults = new CvwDefaults();
            objCvwDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);
            if (objCvwOperations.lstCVarvwOperationsForWhatsAPP != null && objCvwOperations.lstCVarvwOperationsForWhatsAPP.Count > 0) {
                objCvwOperationsMaster.GetListPaging(10, 1, "Where id =" + objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mMasterOperationID, " ID DESC ", out _RowCount2);
                if (objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP.Count>0)
                IsCpWorld = !string.IsNullOrEmpty(objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].MasterBL) && objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].MasterBL.StartsWith("UNI");
            }
            if (objCvwOperations.lstCVarvwOperationsForWhatsAPP != null && objCvwOperations.lstCVarvwOperationsForWhatsAPP.Count > 0 && !(objCvwDefaults.lstCVarvwDefaults[0].mCompanyLocalName == "CPWORLD EGYPT" && IsCpWorld))
            {
                if (_RowCount2 > 0)
                {


                    #region ETD
                    DateTime mExpectedDeparture = DateTime.Parse(objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mExpectedDeparture.ToString());
                    var mExpectedDepartureOnly = mExpectedDeparture.ToString("d/M/yyyy");
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mNetworkName = (mExpectedDepartureOnly == "1/1/1900" ? "" : mExpectedDepartureOnly);
                    #endregion
                    #region ETA
                    DateTime mExpectedArrival = DateTime.Parse(objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mExpectedArrival.ToString());
                    var mExpectedArrivalOnly = mExpectedArrival.ToString("d/M/yyyy");
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mConsigneeAddress = (mExpectedArrivalOnly == "1/1/1900" ? "" : mExpectedArrivalOnly);
                    #endregion
                    #region ATA
                    DateTime mActualArrival = DateTime.Parse(objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mActualArrival.ToString());
                    var mActualArrivalOnly = mActualArrival.ToString("d/M/yyyy");
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mNotifyAddress = (mActualArrivalOnly == "1/1/1900" ? "" : mActualArrivalOnly);
                    #endregion
                    #region StorageDate
                    DateTime mWareHouseEntryDate = DateTime.Parse(objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mWareHouseEntryDate.ToString());
