                    #endregion
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mPOLName = objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mPOLName;
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mPOLCountryName = objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mPOLCountryName;
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mPODName = objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mPODName;
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mPODCountryName = objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mPODCountryName;
                    objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mVesselName = objCvwOperationsMaster.lstCVarvwOperationsForWhatsAPP[0].mVesselName;

                    if (objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mStoreLocation == "0")
                    {
                        CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
                        var WarehouseName = objCCustomizedDBCall.CallStringFunction("select WarehouseName from vwOperationsForBindTableRows Where WarehouseName is not null And HouseNumber = '" + data.pHouseNumber + "'");
                        objCvwOperations.lstCVarvwOperationsForWhatsAPP[0].mStoreLocation = (WarehouseName == "" ? "جاري تحديث البيانات" : WarehouseName);
