        public object HouseAndClientSave([FromBody] HouseFilterChatBodySave data)
        {
            string connectionString = ConfigurationManager.ConnectionStrings["ConnectionString"].ToString();
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var IsExist = objCCustomizedDBCall.CallStringFunction("select id from whatsapp where HouseNumber='" + data.pHouseNumber + "' And PhoneNumber='" + data.pClientPhone + "'");
            string insertQuery = "INSERT INTO WhatsApp (Name, HouseNumber, PhoneNumber) VALUES (@Name, @HouseNumber, @PhoneNumber)";
            if (IsExist == "")
            {
                using (SqlConnection connection = new SqlConnection(connectionString))
                using (SqlCommand command = new SqlCommand(insertQuery, connection))
                {
                    command.Parameters.AddWithValue("@Name", data.pClientName);
                    command.Parameters.AddWithValue("@HouseNumber", data.pHouseNumber);
                    command.Parameters.AddWithValue("@PhoneNumber", data.pClientPhone);

                    connection.Open();
                    command.ExecuteNonQuery();
                }
            }
            return new object[] { };
        }



