        [HttpGet, HttpPost]
        public async Task<object> ReceivePaymentTransactionDetails(PaymentTransactionNotificationModel request)
        {
            var _result = false;
            int _RowCount = 0;
            CvwDefaults objCvwDefaults = new CvwDefaults();
            objCvwDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);
            try
            {

                string rawJson = string.Empty;
                using (var reader = new StreamReader(HttpContext.Current.Request.InputStream))
                {
                    HttpContext.Current.Request.InputStream.Position = 0;
                    rawJson = await reader.ReadToEndAsync();
                }

                CPaymentTransactionNotification objCPaymentTransactionNotification = new CPaymentTransactionNotification();
                CVarPaymentTransactionNotification VarPaymentTransactionNotification = new CVarPaymentTransactionNotification();
                VarPaymentTransactionNotification.ID = 0;
                VarPaymentTransactionNotification.IntegrationId = request.integrationId.ToString();
                VarPaymentTransactionNotification.TransactionId = request.transactionId;
                VarPaymentTransactionNotification.AggregatorOrderId = request.aggregatorOrderId;
                VarPaymentTransactionNotification.OrderId = request.order.id;
                VarPaymentTransactionNotification.OrderDescription = rawJson;
                VarPaymentTransactionNotification.OrderCustomerName = request.order.customer.name;
