                              ""type"": ""sms""
                            }}
                          ]
                        }}", System.Text.Encoding.UTF8, "application/json");
                        request.Content.Headers.ContentType = MediaTypeHeaderValue.Parse("application/json");
                        var response = await httpClient.SendAsync(request);
                        if (response.IsSuccessStatusCode)
                        {
                            var ResponseData_Orders = (await response.Content.ReadAsStringAsync());
                            JObject json_Order = JObject.Parse(ResponseData_Orders);
                            string responseText = await response.Content.ReadAsStringAsync();
                            bool success = json_Order["success"] != null && (bool)json_Order["success"];
                            var serializer = new JavaScriptSerializer();
                            dynamic outer = serializer.Deserialize<dynamic>(responseText);
                            string innerJson = outer["value"];
                            dynamic inner = serializer.Deserialize<dynamic>(innerJson);
                            paymentLink = inner["paymentLink"];
                            _result = true;
                            CSendPaymentTransaction ObjCSendPaymentTransaction = new CSendPaymentTransaction();
                            CVarSendPaymentTransaction VarSendPaymentTransaction = new CVarSendPaymentTransaction();

                            VarSendPaymentTransaction.ID = 0;
                            VarSendPaymentTransaction.HouseNumber = objCvwInvoicesINV.lstCVarvwInvoices[0].HouseNumber;
