                            VarSendPaymentTransaction.OrderDescription = objCvwInvoicesINV.lstCVarvwInvoices[0].InvoiceNumber.ToString();
                            VarSendPaymentTransaction.OrderCustomerName = data.pClientName;
                            VarSendPaymentTransaction.OrderCustomerPhone = data.pClientPhone;
                            VarSendPaymentTransaction.OrderAmountCents = objCvwInvoicesINV.lstCVarvwInvoices[0].Amount;
                            VarSendPaymentTransaction.OrderCurrency = objCvwInvoicesINV.lstCVarvwInvoices[0].CurrencyCode;
                            VarSendPaymentTransaction.OrderCreatedAt = DateTime.Now; ;
                            ObjCSendPaymentTransaction.lstCVarSendPaymentTransaction.Add(VarSendPaymentTransaction);

                            var ExcInsertSendPaymentTransaction = ObjCSendPaymentTransaction.SaveMethod(ObjCSendPaymentTransaction.lstCVarSendPaymentTransaction);

                        }
                        else
                        {
                            _result = false;
                        }
                    }

                    return new { Result = _result, paymentLink = paymentLink };

                }

                else
                {
                    return new { Result = _result, paymentLink = "" };

                }
            }
            catch (Exception exx) {  
                return new { Result = false, paymentLink = "ErrorCatch " + exx.Message };
            }
        }




