        public void CreateSimpleQRCode(string Invoicenumber,long InvoiceID)
        {

            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var AggregatorOrderId = objCCustomizedDBCall.CallStringFunction("select AggregatorOrderId from SendPaymentTransaction where OrderDescription='" + Invoicenumber + "'");
            var TransactionId = objCCustomizedDBCall.CallStringFunction("select TransactionId from PaymentTransactionNotification where AggregatorOrderId='" + AggregatorOrderId + "'");
   

            string qrData = AggregatorOrderId + "/" + TransactionId;
            QRCodeGenerator qrGenerator = new QRCodeGenerator();
            QRCodeData qrCodeData = qrGenerator.CreateQrCode(qrData, QRCodeGenerator.ECCLevel.Q);
            QRCode qrCode = new QRCode(qrCodeData);
            Bitmap qrCodeImage = qrCode.GetGraphic(10, Color.Black, Color.White, false);
            byte[] data;
            using (System.IO.MemoryStream stream = new System.IO.MemoryStream())
            {
                qrCodeImage.Save(stream, System.Drawing.Imaging.ImageFormat.Png);
                data = stream.ToArray();
            }


            objCCustomizedDBCall.CallStringFunctionWithImage("update Invoices set QRImage=@img where ID=" + InvoiceID
                , data);
        }


        //-----------------------------------------------

        public string ShipsGoTracking(Models.Operations.Operations.Generated.Old.CVarOperations cVarOperations, string companyName, bool isTracked)
        {
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            string IsShipsGoTracked = objCCustomizedDBCall.CallStringFunction("select count(*) from ShipsGoSettings");
            if (string.IsNullOrWhiteSpace(IsShipsGoTracked))
            {
                IsShipsGoTracked = "0";
            }
            if (int.Parse(IsShipsGoTracked) == 1) //Meaning Shipsgo tracking is enabled here
            {
                string IsHavingCredit = objCCustomizedDBCall.CallStringFunction("select top 1 case when ISNULL(MaximumCount,0)>CurrentCount then 1 else 0 end from ShipsGoSettings");
                if (IsHavingCredit == "1") // Have Credit
                {
                    //Check Shipping Line is supported
                    string IsShipsGoSLSupported = objCCustomizedDBCall.CallStringFunction($"select count(*) from ShipsGoSupportedShippingLines WHERE ShippingLineID={cVarOperations.ShippingLineID}");
                    if (string.IsNullOrWhiteSpace(IsShipsGoSLSupported))
                    {
                        IsShipsGoSLSupported = "0";
                    }
                    if (int.Parse(IsShipsGoSLSupported) == 0)
                    {
                        return "Shipping Line Not Supported";
                    }

                    int custID = cVarOperations.DirectionType == 2 ? cVarOperations.ShipperID : cVarOperations.ConsigneeID;
                    string IsCustomerHaveTrackingOption = objCCustomizedDBCall.CallStringFunction($"select ID from ShipsGoCustomers where CustomerID={custID}");

                    if (companyName != "ELI")
                    {
                        isTracked = true;
                    }

                    if (string.IsNullOrWhiteSpace(IsCustomerHaveTrackingOption))
                    {
                        IsCustomerHaveTrackingOption = "0";
                    }
                    if (isTracked && int.Parse(IsCustomerHaveTrackingOption) > 0) // Customer Tracked
                    {
                        ShipsGoAPIController _ShipsGoAPIController = new ShipsGoAPIController();
                        Container trackedMBL = _ShipsGoAPIController.TrackNewShipment(cVarOperations.MasterBL, cVarOperations.ID)[0];

                        if (trackedMBL.Message != "Success")
                        {
                            return trackedMBL.Message;
                        }

                        Exception ex = _ShipsGoAPIController.InsertShipsGoBL(trackedMBL, cVarOperations.ID, "I", custID, 0);

                        if (ex != null)
                            return ex.Message;
                        else
                            return "";
                    }
                    else // Customer Not Tracked
                    {
                        return "";
                    }

                } else // Limit Reached
                {
                    return "Tracking Limit Reached !!";
                }

            } else
            {
                return "";
            }

        }

