            if (IsMescoCompany && insertOperationData.pIsShipment == false && insertOperationData.pMasterBL != "0" && insertOperationData.pMasterBL != "" && insertOperationData.pTransportType == "1" && insertOperationData.pBLType == "3" && (insertOperationData.pShipmentType == "5" || insertOperationData.pShipmentType == "2"))
            {
