                        updateClause += updateOperationData.pCutOffDate == "0" ? " ,CutOffDate = NULL " : (" ,CutOffDate = '" + (DateTime.ParseExact(updateOperationData.pCutOffDate + " 00.00.00.000", "dd/MM/yyyy hh.mm.ss.fff", CultureInfo.InvariantCulture)).ToString("yyyyMMdd") + "'");

                    updateClause += " , IsDelivered = " + (updateOperationData.pIsDelivered ? "1" : "0");
                    updateClause += " , IsTrucking = " + (updateOperationData.pIsTrucking ? "1" : "0");
                    updateClause += " , IsInsurance = " + (updateOperationData.pIsInsurance ? "1" : "0");
                    updateClause += " , IsClearance = " + (updateOperationData.pIsClearance ? "1" : "0"); //Updated from clearance and used as IsVesselArrived
                    updateClause += " , IsGenset = " + (updateOperationData.pIsGenset ? "1" : "0");
                    updateClause += " , IsCourrier = " + (updateOperationData.pIsCourrier ? "1" : "0");
                    updateClause += " , IsTelexRelease = " + (updateOperationData.pIsTelexRelease ? "1" : "0");
                    updateClause += " , NetworkID = " + (updateOperationData.pNetworkID == 0 ? " NULL " : updateOperationData.pNetworkID.ToString());
                    updateClause += " , NumberOfOriginalBills = " + (updateOperationData.pNumberOfOriginalBills == 0 ? " NULL " : "'" + updateOperationData.pNumberOfOriginalBills + "' ");

                    updateClause += " , ModificatorUserID = " + WebSecurity.CurrentUserId.ToString();
                    ////next line to be deleted
                    //updateClause += (updateOperationData.pOpenDate == "" ? " ,CreationDate = NULL " : " ,CreationDate = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(updateOperationData.pOpenDate, 2) + "'");
                    updateClause += " , ModificationDate = GETDATE() ";

                    updateClause += " WHERE ID = " + OperationID;
                    Exception checkException = objCOperationsTax.UpdateList(updateClause);
                    if (checkException != null) // an exception is caught in the model
                    {
                        if (checkException.Message.Contains("UNIQUE"))
                            _result = false;
                    }
                    else
                    {//not unique
                        _result = true;
                        Operations_EmailNotification(updateOperationData.pID);
                    }



                } //if (_MessageReturned == "")
            }

            if (CompanyName == "ELI")
            {
                CRoutings objCRoutings = new CRoutings();
                var ex = objCRoutings.UpdateList($"CertificateNumber='{updateOperationData.pForm13Number}', CCAInvoiceNumber='{updateOperationData.pCustomerReference}' where OperationID={updateOperationData.pID} and RoutingTypeID=70");
            }

            InsertOperationTracking(new Models.Operations.Operations.Generated.Old.CVarOperations
            {
                ID = updateOperationData.pID,
                DirectionType = updateOperationData.pDirectionType,
                TransportType = updateOperationData.pTransportType
            }, CompanyName);

            return new Object[] {
                _result
                , updateOperationData.pID
                , _MessageReturned //pData[2] 
            };
        }


        Exception InsertOperationTracking(Models.Operations.Operations.Generated.Old.CVarOperations pOperation, string pCompanyName = "")
        {
            if (string.IsNullOrWhiteSpace(pCompanyName))
            {
                CDefaults objCDefaults = new CDefaults();
                objCDefaults.GetList($" where ID = (select IsNull(Max(ID),0) from Defaults) ");
                pCompanyName = objCDefaults.lstCVarDefaults[0].UnEditableCompanyName;
            }
            if (!(new string[] { "ELI", "MR" }.Contains(pCompanyName)))
            {
                return null;
            }
            if (pOperation == null || pOperation.ID == 0)
            {
                return new Exception("Operation Not Exist!");
            }
            COperationTracking objCOperationTracking = new COperationTracking();
            objCOperationTracking.GetList($" where OperationID = {pOperation.ID} ");
            if (objCOperationTracking.lstCVarOperationTracking.Count > 0)
            {
                return new Exception("Operation Tracking Exist!");
            }
            string whereClause = " where 1 = 1 ";
            switch (pOperation.DirectionType)
            {
                case 1: whereClause += " and IsImport = 1"; break;
                case 2: whereClause += " and IsExport = 1"; break;
                case 3: whereClause += " and IsDomestic = 1"; break;
            }
            switch (pOperation.TransportType)
            {
                case 1: whereClause += " and IsOcean = 1"; break;
                case 2: whereClause += " and IsAir = 1"; break;
                case 3: whereClause += " and IsInland = 1"; break;
            }
            var objCTrackingStage = new CTrackingStage();
            Exception checkException = objCTrackingStage.GetList(whereClause);

            var datetimeNow = DateTime.Now;

            foreach (var item in objCTrackingStage.lstCVarTrackingStage)
            {
                objCOperationTracking.lstCVarOperationTracking.Add(new CVarOperationTracking
                {
                    OperationID = pOperation.ID,
                    TrackingStageID = item.ID,
                    CreatorUserID = WebSecurity.CurrentUserId,
                    ModificatorUserID = WebSecurity.CurrentUserId,
                    CreationDate = datetimeNow,
                    ModificationDate = datetimeNow
                });
                Common.Common.ReplaceNull(objCOperationTracking.lstCVarOperationTracking[objCOperationTracking.lstCVarOperationTracking.Count - 1]);
            }
            checkException = objCOperationTracking.SaveMethod(objCOperationTracking.lstCVarOperationTracking);
            return checkException;
        }
        Exception CheckBookingNo(long pOprationID, string pBookingNo, string pCompanyName = "")
        {
            if (string.IsNullOrWhiteSpace(pCompanyName))
            {
                CDefaults objCDefaults = new CDefaults();
                objCDefaults.GetList($" where ID = (select IsNull(Max(ID),0) from Defaults) ");
                pCompanyName = objCDefaults.lstCVarDefaults[0].UnEditableCompanyName;
            }
            if (pCompanyName != "ELI" && pCompanyName != "NAJ")
            {
                return null;
            }
            if (string.IsNullOrWhiteSpace(pBookingNo) || pBookingNo == "0")
            {
                return null;
            }

            var objCOperations = new COperations();
            var exception = objCOperations.GetList($" where BookingNumber = '{pBookingNo}' and ID <> {pOprationID} and IsNull(MasterOperationID,0)=0 ");
            if (objCOperations.lstCVarOperations.Count > 0)
                return new Exception($" Booking No Exist In Operation {objCOperations.lstCVarOperations[0].CodeSerial} ");

            if (pCompanyName == "NAJ" && pOprationID > 0)
            {
                CBookings objCBookings = new CBookings();
                Exception e = objCBookings.GetList($"where BookingNumber=N'{pBookingNo}'");
                if (e != null)
                    return e;
                else if (objCBookings.lstCVarBookings.Count == 0)
                    return null;
                else if (objCBookings.lstCVarBookings.Count > 0)
                {
                    if (objCBookings.lstCVarBookings[0].OperationID == 0)
                    {
                        COperations objCheckDates = new COperations();
                        e = objCheckDates.GetItem(pOprationID);
                        if (e != null)
                            return e;

                        if (objCheckDates.lstCVarOperations[0].OpenDate > objCBookings.lstCVarBookings[0].ValidatedTitlesDate)
                        {
                            return new Exception($"Check Validated Titles Date...");
                        }
                        else
                        {
                            e = objCBookings.UpdateList($"OperationID={pOprationID} WHERE ID={objCBookings.lstCVarBookings[0].ID}");
                            if (e != null)
                                return e;
                        }
                    }
                    else
                    {
                        if (objCBookings.lstCVarBookings[0].OperationID != pOprationID)
                        {
                            return new Exception($"Booking No. Linked With Another Operation");
                        } else
                        {
                            return null;
                        }
                    }
                }

            }
            //var objCvwRoutings = new CvwRoutings();
            //exception = objCvwRoutings.GetList($" where BookingNumber = '{pBookingNo}' and OperationID <> {pOprationID} and IsNull(MasterOperationID,0)=0  ");
            //if (objCvwRoutings.lstCVarvwRoutings.Count > 0)
            //    return new Exception($" Booking No Exist In Operation Routing {objCvwRoutings.lstCVarvwRoutings[0].OperationSerial} ");
            return null;
        }
        [HttpGet, HttpPost]
        public object[] ApproveService(Int64 pOperationID, string pServiceToApprove, Int32 pIsApprove)
        {
            string _ReturnedMessage = "";
            string _UpdateClause = "";
            int _RowCount = 0;
            Exception checkException = null;
            COperations objCOperations = new COperations();

            _UpdateClause = "Is" + pServiceToApprove + "Approved = " + pIsApprove + " \n";
            _UpdateClause += ", " + pServiceToApprove + "ApprovalDate = GETDATE()" + " \n";
            _UpdateClause += "WHERE ID=" + pOperationID;
            checkException = objCOperations.UpdateList(_UpdateClause);
            checkException = objCOperations.GetListPaging(999999, 1, "WHERE ID=" + pOperationID, "ID", out _RowCount);
            var serilizer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new object[]
            {
                _ReturnedMessage
                , serilizer.Serialize(objCOperations.lstCVarOperations[0])
            };
        }
