                    }

                    else
                    {

                        string pNewCodePartner = objCCustomizedDBCall.CallStringFunction("SELECT [dbo].A_CostCenters_GetCode(" + (pID == 0 ? "null" : pID.ToString()) + ") AS Code");


                        CVarA_CostCenters objCVarA_CostCenters = new CVarA_CostCenters();
