                        checkException = objA_LinkOperationWithCostCenter.SaveMethod(objA_LinkOperationWithCostCenter.lstCVarA_LinkOperationWithCostCenter);
                    }

                }


                #endregion
            }
            return new object[] { _result, _result ? objCOperations.lstCVarOperations[0].ID : 0 };
        }

        [HttpGet, HttpPost]
        public object[] Delete(String pDeletedOperationsIDs)
        {
            bool _result = false;
            COperations objCOperations = new COperations();
            foreach (var currentID in pDeletedOperationsIDs.Split(','))
            {
                objCOperations.lstDeletedCPKOperations.Add(new CPKOperations() { ID = Int32.Parse(currentID.Trim()) });
            }

            Exception checkException = objCOperations.DeleteItem(objCOperations.lstDeletedCPKOperations);
            if (checkException != null) // an exception is caught in the model
            {
                if (checkException.Message.Contains("DELETE")) // some or all of the rows were not deleted due to dependencies
                    _result = false;
            }
            else //deleted successfully
                _result = true;
            return new object[] {
                _result ? "" : checkException.Message
            };
        }

        //Set OperationStage
        [HttpGet, HttpPost]
        public object[] SetOperationStage(Int64 pID, int pOperationStageID, string pCloseDate/*used just in case of ReOpening an Operation, its in yyyyMMdd Format*/)
        {
            int _RowCount = 0;
            string updateClause = "";
            string pReturnedMessage = "";
            int ClosedQuoteAndOperStageID = 120;
            int OpenQuoteAndOperStageID = 60;
            var CancelledQuoteAndOperStageID = 110;
            var RLReadyOperStageID = 130;
            CCustomizedDBCall CCustomizedDBCall = new CCustomizedDBCall();
            Exception exception = null;
            CPayables objCPayables = new CPayables();
            CReceivables objCReceivables = new CReceivables();
            CDefaults objCDefaults = new CDefaults();
            objCDefaults.GetListPaging(1, 1, "", "ID", out _RowCount);
            var operation = CCustomizedDBCall.ExecuteQuery_ListOfObjects("Select TransportType,MasterBL from Operations Where ID = " + pID, typeof(CVarOperations)).Cast<CVarOperations>().ToList();
            string operationMasterBL = operation[0].MasterBL;
            int operationTransportType = operation[0].TransportType;
            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "EVL" && operationTransportType == 1 && pOperationStageID == ClosedQuoteAndOperStageID && (operationMasterBL == null || operationMasterBL == "" || operationMasterBL == "0"))
            {
                return new object[] {
                  "Operation Must Has MasterBL!"
                };
            }
            string[] MescoCompanies = new string[5] { "MES", "SAC", "GLO", "EUR", "ALT" };
            bool IsMescoCompany = MescoCompanies.Contains(objCDefaults.lstCVarDefaults[0].UnEditableCompanyName);
            if (IsMescoCompany && (pOperationStageID == ClosedQuoteAndOperStageID || pOperationStageID == RLReadyOperStageID))
            {
                objCReceivables.GetListPaging(1, 1, "WHERE IsDeleted=0 AND OperationID=" + pID + " AND InvoiceID IS NULL AND AccNoteID IS NULL", "ID", out _RowCount);
                if (objCReceivables.lstCVarReceivables.Count > 0)
                    pReturnedMessage = "There are receivables with no invoice or debit note, Please check!";
            }
            else if (IsMescoCompany && pOperationStageID == CancelledQuoteAndOperStageID)
            {
                CInvoices objCInvoices = new CInvoices();
                objCInvoices.GetListPaging(1, 1, "WHERE IsDeleted=0 AND OperationID=" + pID, "ID", out _RowCount);
                if (objCInvoices.lstCVarInvoices.Count > 0)
                {
                    pReturnedMessage = "Can't cancel operation because it has an invoice";
                    return new object[] {
                        pReturnedMessage
                    };
                }

                CAccNote objCAccNote = new CAccNote();
                objCAccNote.GetListPaging(1, 1, "WHERE IsDeleted=0 and OperationID=" + pID, "ID", out _RowCount);
                if (objCAccNote.lstCVarAccNote.Count > 0)
                {
                    pReturnedMessage = "Can't cancel operation because it has a C/D Note";
                    return new object[] {
                        pReturnedMessage
                    };
                }

                CA_PaymentRequestDetails objCA_PaymentRequestDetails = new CA_PaymentRequestDetails();
                objCA_PaymentRequestDetails.GetListPaging(1, 1, "WHERE OperationID=" + pID, "ID", out _RowCount);
                if (objCA_PaymentRequestDetails.lstCVarA_PaymentRequestDetails.Count > 0)
                {
                    pReturnedMessage = "Can't cancel operation because Payable Exists in Payment Request";
                    return new object[] {
                        pReturnedMessage
                    };
                }
            }


            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "AKS" && pOperationStageID == ClosedQuoteAndOperStageID)
            {
                CRoutings MainRoute = new CRoutings();
                MainRoute.GetListPaging(99999, 1, " Where operationID= " + Convert.ToInt32(pID) + " and routingtypeid = 30", "ID DESC", out _RowCount);
                var x = MainRoute.lstCVarRoutings[0].ETAPOLDate;
                var x1 = MainRoute.lstCVarRoutings[0].ExpectedDeparture;
                var x2 = MainRoute.lstCVarRoutings[0].ExpectedArrival;
                var x3 = MainRoute.lstCVarRoutings[0].ActualArrival;
                var x4 = MainRoute.lstCVarRoutings[0].DeliveryDate;

                if (/*x.Year <2000 || x1.Year <2000|| x2.Year < 2000 ||*/ x3.Year < 2000 || x4.Year < 2000)
                {
                    return new object[] {
                      pReturnedMessage = " cannot close job before entering D/O date , ATA POD"
                  };


                }
            }

            if (IsMescoCompany && pOperationStageID == RLReadyOperStageID)
            {
                //objCReceivables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //            + " AND IsDeleted=0 AND CategoryID=6 ", "ID", out _RowCount);

                //objCPayables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //      + " AND IsDeleted=0 AND CategoryID=6 ", "ID", out _RowCount);

                //objCReceivables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //+ " AND IsDeleted=0 AND CategoryID=6 and SaleAmount > 0", "ID", out _RowCount);

                //objCPayables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //      + " AND IsDeleted=0 AND CategoryID=6 and CostAmount > 0", "ID", out _RowCount);

                //decimal totalCostAmount = objCPayables.lstCVarPayables.Sum(Payables => Payables.CostAmount == 0 ? Payables.QuotationCost : Payables.CostAmount);
                //decimal totalSalesAmount = objCReceivables.lstCVarReceivables.Sum(receivable => receivable.SaleAmount);
                Exception checkException = null;
                CvwOperations objCvwOperations = new CvwOperations();
                CvwReceivables objCvwReceivables = new CvwReceivables();
                CvwInvoices objCvwInvoices = new CvwInvoices();

                objCvwOperations.GetListPaging(99999, 1, " Where ID= " + Convert.ToInt32(pID), "ID DESC", out _RowCount);

                checkException = objCvwReceivables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                    + " AND IsDeleted=0 AND InvoiceID IS NULL AND AccNoteID IS NULL ", "ID", out _RowCount);

                if (objCvwReceivables.lstCVarvwReceivables.Count > 0)
                    pReturnedMessage = " Please Create Invoice For Remaining Receivables ,Operation Code " + objCvwReceivables.lstCVarvwReceivables[0].OperationCode;

                checkException = objCvwInvoices.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                    + " AND IsDeleted=0 AND IsApproved <> 1", "ID", out _RowCount);

                if (objCvwInvoices.lstCVarvwInvoices.Count > 0)
                    pReturnedMessage = " Please Approved Invoices First ,Operation Code " + objCvwInvoices.lstCVarvwInvoices[0].OperationCode;


                //checkException = objCvwInvoices.GetListPaging(
                //                                              999999,
                //                                              1,
                //                                              "WHERE (OperationID = " + pID +
                //                                              " OR OperationID IN (SELECT ID FROM Operations WHERE MasterOperationID = " + pID +
                //                                              ")) AND IsDeleted = 0 AND InvoiceTypeID = 9 AND ChildInvoiceID IS NULL",
                //                                              "ID",
                //                                              out _RowCount
                //                                          );




                var IsDraftsValid = CCustomizedDBCall.CallStringFunction($"CheckInvoicesValidation {pID}");


                if (IsDraftsValid != "1")
                    pReturnedMessage = " Cannot Close Operation There IS Draft With Out Invoice ," + (objCvwOperations.lstCVarvwOperations[0].BLType == 2 ? "House Num " + objCvwInvoices.lstCVarvwInvoices[0].HouseNumber : "Operation Code " + objCvwOperations.lstCVarvwOperations[0].Code);

                //checkException = objCvwReceivables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //+ " AND IsDeleted=0 AND CategoryID=6 and SaleAmount > 0  and (select InvoiceStatus from vwinvoices where id = InvoiceID ) != 'Cancelled by credit note' ", "ID", out _RowCount);

                //checkException = objCPayables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //      + "and (isnull(accnoteid , 0 ) = 0) AND IsDeleted=0 AND CategoryID=6 and CostPrice > 0", "ID", out _RowCount);

                //decimal totalCostAmount = Math.Round(objCPayables.lstCVarPayables.Sum(Payables => Payables.CostPrice * Payables.Quantity), 2);
                //decimal totalSalesAmount = Math.Round(objCvwReceivables.lstCVarvwReceivables.Sum(receivable => receivable.SaleAmount), 2);

                var IsValidOfficialReceipt = CCustomizedDBCall.CallStringFunction($"CheckOfficialAmounts {pID}");


                if (IsValidOfficialReceipt != "1")
                    pReturnedMessage = "client official receipt payables and receivables not equal ";






                //objCReceivables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //+ " AND IsDeleted=0 AND CategoryID=6 and SaleAmount > 0", "ID", out _RowCount);

                //objCPayables.GetListPaging(999999, 1, " WHERE OperationID = " + pID
                //      + " AND IsDeleted=0 AND CategoryID=6 and CostPrice > 0", "ID", out _RowCount);

                //decimal totalCostAmount = Math.Round(objCPayables.lstCVarPayables.Sum(Payables => Payables.CostPrice * Payables.Quantity), 2);
                //decimal totalSalesAmount = Math.Round(objCReceivables.lstCVarReceivables.Sum(receivable => receivable.SaleAmount), 2);


                //if (totalCostAmount != totalSalesAmount)
                //    pReturnedMessage = "client official receipt payables and receivables not equal ";

                objCPayables.GetListPaging(999999, 1, "where (isnull(QuotationCost,0)=0 And isnull(CostAmount , 0)=0) AND IsDeleted=0 and OperationID =" + pID, "ID", out _RowCount);

                if (_RowCount > 0)
                    pReturnedMessage = "There is Payable WithOut EstimatedCost/ActualCost. ";


                exception = CCustomizedDBCall.CallProcFunction($"Mesco_Operation_Closing_Validation {pID} ");
                if (exception != null)
                {

                    pReturnedMessage = exception.Message;


                }

            }

            if (pReturnedMessage == "")
            {
                if (pOperationStageID == CancelledQuoteAndOperStageID)
                {
                    objCPayables.GetListPaging(1, 1, "WHERE IsDeleted=0 AND OperationID=" + pID, "ID", out _RowCount);
                    objCReceivables.GetListPaging(1, 1, "WHERE IsDeleted=0 AND OperationID=" + pID, "ID", out _RowCount);
                }
                if (!IsMescoCompany && (objCReceivables.lstCVarReceivables.Count > 0 || objCPayables.lstCVarPayables.Count > 0))
                    pReturnedMessage = "Please, check there is not payables nor receivables.";
                else
                {
                    updateClause = " OperationStageID = " + pOperationStageID.ToString();
                    if (!IsMescoCompany)
                    {


                        updateClause += (pOperationStageID == ClosedQuoteAndOperStageID ? " , CloseDate = GETDATE() " : "");//pOperationStageID == 110 i.e. Closed
                        updateClause += (pOperationStageID == OpenQuoteAndOperStageID ? " , CloseDate = '" + pCloseDate + "'" : "");
                        if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "COS")
                        {
                            updateClause += (pOperationStageID == 65 ? " , TruckingApprovalDate = '" + pCloseDate + "'" : "");
                        }

                    }
                    updateClause += " , ModificatorUserID = " + WebSecurity.CurrentUserId.ToString();
                    updateClause += " , ModificationDate = GETDATE() ";
                    updateClause += "            WHERE ID = " + pID.ToString() + " OR MasterOperationID=" + pID.ToString();

                    COperations objCOperations = new COperations();
                    Exception checkException = objCOperations.UpdateList(updateClause);
                    if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "FWD" && pOperationStageID == CancelledQuoteAndOperStageID && checkException == null)
                    {
                        var CancelledOperation = new COperations();
                        checkException = CancelledOperation.UpdateList($" QuotationRouteID=NULL WHERE ID={pID} OR MasterOperationID={pID}");
                    }
                    if (checkException != null)
                        pReturnedMessage = checkException.Message;
                    else
                    {
                        var objCCustomizedDBCall = new CCustomizedDBCall();
                        objCCustomizedDBCall.ExecuteQuery($"INSERT INTO OperationStagesLog(OperationID,StageID,UserID) VALUES ({pID},{pOperationStageID},{WebSecurity.CurrentUserId})");

                        if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UTS" && pOperationStageID == ClosedQuoteAndOperStageID)
                        {
                            CCallCustomizedSP objCCallCustomizedSP = new CCallCustomizedSP();
                            checkException = objCCallCustomizedSP.CallCustomizedSP("ERP_ForwWeb_PostingCloseOperation", pID, WebSecurity.CurrentUserId, true, 0);
                        }
                    }
                }
            }
            return new object[] {
                pReturnedMessage
            };
        }
