                            if (int.TryParse(CountOfHouses, out int countH))
                            {
                                updateClause += " , HouseNumber=N'" + objCOperations.lstCVarOperations[0].CodeSerial + "/" + (countH + 1) + "' \n";
                            }

                        }

                        updateClause += "            WHERE ID = " + pHouseOperationID.ToString();

                        checkException = objCOperations.UpdateList(updateClause);
                        if (checkException == null)
                        {
                            _result = true;
                            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "UNF" && pAction == "" && pIsHouseConnected)
                            {
                                var objCOperationContainersAndPackagesForUNFLink = new COperationContainersAndPackages();
                                objCOperationContainersAndPackagesForUNFLink.GetListPaging(1, 1, $"WHERE OperationID={pMasterOperationIDFieldInHouse}", "ID", out _);
                                if (objCOperationContainersAndPackagesForUNFLink.lstCVarOperationContainersAndPackages.Count == 1)
                                {
                                    COperationContainersAndPackagesPlacedOn LinkUNFHouse = new COperationContainersAndPackagesPlacedOn();
                                    var itemPO = new CVarOperationContainersAndPackagesPlacedOn()
                                    {
