                                    cont.ReturnDepot = "0";
                                    cont.OperatorID = 0;
                                    cont.StatusID = 0;

                                    cont.IsFull = false;
                                    cont.ExitDate = DateTime.Parse("01/01/1900");
                                    cont.ReturnDate = DateTime.Parse("01/01/1900");
                                    cont.TankCertExpiryDate = DateTime.Parse("01/01/1900");
                                    cont.FreeDays = 0;
                                    cont.DayValue = 0;
                                    #endregion Tank
                                    #region Yard
                                    cont.YardEIRNumber = 0;
                                    cont.YardEIRNumberOut = 0;
                                    cont.YardInDate = DateTime.Parse("01/01/1900");
                                    cont.YardInTime = 0;
                                    cont.YardOutDate = DateTime.Parse("01/01/1900");
                                    cont.YardOutTime = 0;
                                    cont.YardLocationID = 0;
                                    cont.YardIsIn = 0;
                                    #endregion Yard

                                    cont.CreatorUserID = cont.ModificatorUserID = WebSecurity.CurrentUserId;
                                    cont.CreationDate = cont.ModificationDate = DateTime.Now;

                                    OPCP.lstCVarOperationContainersAndPackages.Add(cont);

                                    Exception e3 = OPCP.SaveMethod(OPCP.lstCVarOperationContainersAndPackages);
                                    if (e3 == null)
                                    {
                                        COperationContainersAndPackagesPlacedOn LinkHouseFromTransfer = new COperationContainersAndPackagesPlacedOn();
                                        LinkHouseFromTransfer.DeleteList($"WHERE OperationID={pHouseOperationID}");
                                        var itemPOFromTransfer = new CVarOperationContainersAndPackagesPlacedOn()
                                        {
