        //Connect Or Disconnect Houses to Master
        [HttpGet, HttpPost]
        public object[] ConnectOrDisconnectMultiple(Int64 pMasterOperationID, bool pIsHouseConnected, Int64 pMasterOperationIDFieldInHouse, string pHouseOperationsIDs, Int64 pHouseParentID, string pAction = "")
        {
            string[] OperationIDsArray = pHouseOperationsIDs.Split(',');
            int NumberOfOperations = OperationIDsArray.Length;
            int _RowCount = 0;
            decimal GrossWeight = 0;
            decimal Volume = 0;
            int NoOfPackages = 0;
            long QuotationrouteId = 0;
            COperations cOperations = new COperations();
            COperationContainersAndPackages cOperationContainersAndPackages = new COperationContainersAndPackages();
            CQuotationCharges cQuotationCharges = new CQuotationCharges();

            CDefaults objCDefaults = new CDefaults();
            objCDefaults.GetList("WHERE 1=1");

            object[] arr = new object[NumberOfOperations];

            for (int i = 0; i < NumberOfOperations; i++)
            {
                arr[i] = ConnectOrDisconnect(pMasterOperationID, pIsHouseConnected, pMasterOperationIDFieldInHouse, Int64.Parse(OperationIDsArray[i]), pHouseParentID, pAction);
                cOperations.GetListPaging(99999, 1, "WHERE ID = " + OperationIDsArray[i], "ID", out _RowCount);
                var Operation = cOperations.lstCVarOperations.FirstOrDefault(o => o.ID == long.Parse(OperationIDsArray[i]));
                GrossWeight += Operation.GrossWeight;
                Volume += Operation.Volume;
                NoOfPackages += Operation.NumberOfPackages;
                QuotationrouteId = Operation.QuotationRouteID;
                if (QuotationrouteId != 0 && objCDefaults.lstCVarDefaults[0].UnEditableCompanyName != "UNF")
                {
                    cQuotationCharges.GetListPaging(99999, 1, "WHERE QuotationRouteID =" + QuotationrouteId, "ID", out _RowCount);
                    var Charges = cQuotationCharges.lstCVarQuotationCharges;
                    foreach (var charge in Charges)
                    {
                        CVarPayables CVarPayables = new CVarPayables();
                        CVarPayables.OperationID = pMasterOperationID;
                        CVarPayables.ChargeTypeID = charge.ChargeTypeID;
                        CVarPayables.POrC = charge.POrC;
                        CVarPayables.ContainerTypeID = charge.ContainerTypeID;
                        CVarPayables.SupplierOperationPartnerID = charge.SupplierID;
                        CVarPayables.MeasurementID = charge.MeasurementID;
                        CVarPayables.Quantity = charge.CostQuantity;
                        CVarPayables.QuotationCost = charge.CostPrice;
                        CVarPayables.CostPrice = 0;
                        CVarPayables.CostAmount = 0;
                        CVarPayables.ExchangeRate = charge.CostExchangeRate;
                        CVarPayables.CurrencyID = charge.CostCurrencyID;
                        CVarPayables.Notes = "Estimated Cost Price = " + charge.CostPrice;
                        CVarPayables.CreatorUserID = WebSecurity.CurrentUserId;
                        CVarPayables.CreationDate = DateTime.Now;
                        CVarPayables.ModificationDate = DateTime.Now;
                        CVarPayables.ModificatorUserID = WebSecurity.CurrentUserId;
                        CVarPayables.IsPurchased = false;

                        if (charge.BillTo != 0)
                        {

                            COperationPartners getBillTo = new COperationPartners();

                            var custNo = "";

                            var OPPTypes = new CNoAccessOperationPartnerTypes();
                            OPPTypes.GetItem(charge.BillTo_OperationPartnerTypeID);
                            if (OPPTypes.lstCVarNoAccessOperationPartnerTypes.Count == 1)
                            {

                                if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 1)
                                {
                                    custNo = $"CustomerID={charge.BillTo}";
                                } else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 2)
                                {
                                    custNo = $"AgentID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 3)
                                {
                                    custNo = $"ShippingAgentID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 4)
                                {
                                    custNo = $"CustomsClearanceAgentID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 5)
                                {
                                    custNo = $"ShippingLineID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 6)
                                {
                                    custNo = $"AirlineID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 7)
                                {
                                    custNo = $"TruckerID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 8)
                                {
                                    custNo = $"SupplierID={charge.BillTo}";
                                }
                                else if (OPPTypes.lstCVarNoAccessOperationPartnerTypes[0].PartnerTypeID == 20)
                                {
                                    custNo = $"CustodyID={charge.BillTo}";
                                }

                                if (custNo != "")
                                {
                                    getBillTo.GetListPaging(1, 1, $"WHERE OperationID={pMasterOperationID} AND OperationPartnerTypeID={charge.BillTo_OperationPartnerTypeID} AND {custNo}", "ID", out _);

                                    if (getBillTo.lstCVarOperationPartners.Count == 1)
                                        CVarPayables.BillTo = getBillTo.lstCVarOperationPartners[0].ID;
                                    else
                                        CVarPayables.BillTo = 0;
                                } else
                                {
                                    CVarPayables.BillTo = 0;
                                }
                            } else
                            {
                                CVarPayables.BillTo = 0;
                            }

                        } else
                        {
                            CVarPayables.BillTo = charge.BillTo;
                        }
                        CVarPayables.BillID = long.Parse(OperationIDsArray[i]);
                        CVarPayables.PricingID = charge.PricingID;
                        CVarPayables.SupplierSiteID = charge.SupplierSiteID;

                        Common.Common.ReplaceNull(CVarPayables);
                        CPayables objCPayables = new CPayables();
                        objCPayables.lstCVarPayables.Add(CVarPayables);
                        Exception checkException = objCPayables.SaveMethod(objCPayables.lstCVarPayables);
                        if (checkException != null)
                        {
                            arr[i] = new Object[] { false, checkException.Message };
                        }
                        CVarReceivables CVarReceivables = new CVarReceivables();
                        CVarReceivables.OperationID = pMasterOperationID;
                        CVarReceivables.ChargeTypeID = charge.ChargeTypeID;
                        CVarReceivables.POrC = charge.POrC;
                        CVarReceivables.SupplierID = charge.SupplierID;
                        CVarReceivables.MeasurementID = charge.MeasurementID;
                        CVarReceivables.ContainerTypeID = charge.ContainerTypeID;
                        CVarReceivables.PackageTypeID = charge.PackageTypeID;
                        if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF")
                        {
                            CVarReceivables.Quantity = charge.CostQuantity;
                            CVarReceivables.CostPrice = charge.CostPrice;
                            CVarReceivables.CostAmount = charge.CostAmount;
                            CVarReceivables.SalePrice = charge.SalePrice;
                            CVarReceivables.SaleAmount = charge.SaleAmount;
                        } else
                        {
                            CVarReceivables.Quantity = charge.SaleQuantity;
                            CVarReceivables.CostPrice = 0;
                            CVarReceivables.CostAmount = 0;
                            CVarReceivables.SalePrice = 0;
                            CVarReceivables.SaleAmount = 0;
                        }
                        CVarReceivables.HouseBillID = int.Parse(OperationIDsArray[i]);
                        CVarReceivables.ExchangeRate = charge.SaleExchangeRate;
                        CVarReceivables.CurrencyID = charge.SaleCurrencyID;
                        CVarReceivables.Notes = "Estimated Sale Amount = " + charge.SaleAmount;
                        CVarReceivables.ViewOrder = charge.ViewOrder;
                        CVarReceivables.CreatorUserID = WebSecurity.CurrentUserId;
                        CVarReceivables.CreationDate = DateTime.Now;
                        CVarReceivables.ModificationDate = DateTime.Now;
                        CVarReceivables.ModificatorUserID = WebSecurity.CurrentUserId;
                        Common.Common.ReplaceNull(CVarReceivables);
                        CReceivables ObjCReceivable = new CReceivables();
                        ObjCReceivable.lstCVarReceivables.Add(CVarReceivables);
                        Exception checkException2 = ObjCReceivable.SaveMethod(ObjCReceivable.lstCVarReceivables);
                        if (checkException2 != null)
                        {
                            arr[i] = new Object[] { false, checkException2.Message };
                        }


                    }
                }
            }
            COperations MasterOperation = new COperations();
            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName != "UNF" || pAction == "")
            {
                //MasterOperation.UpdateList("GrossWeight= "+GrossWeight + ", NumberOfPackages= " + NoOfPackages + ", Volume =" + Volume+" WHERE ID =" + pMasterOperationID);
                var op = new COperations();
                op.GetItem(pMasterOperationID);
                if (op.lstCVarOperations.Count == 1)
                {
                    op.lstCVarOperations[0].GrossWeight = GrossWeight;
                    op.lstCVarOperations[0].Volume = Volume;
                    op.lstCVarOperations[0].NumberOfPackages = NoOfPackages;

                    Exception checkE = op.SaveMethod(op.lstCVarOperations);
                }
            }


            return arr;
        }

        [HttpGet, HttpPost]
        public object[] Shipment_Update([FromBody] Shipment_Update shipment_Update)
            //long pShipmentID, int pBranchID, int pSalesmanID, string pOpenDate,
            //string pHouseNumber, int pPOLCountryID, int pPickupCityID, int pPODCountryID
            //, int pDeliveryCityID, int pShipperID, int pConsigneeID, int pAgentID, int pNotifyID, int pIncotermID,
            //int pMoveTypeID, string pNotes
            //, int pCommodityID, string pCustomerReference, string pSupplierReference, string pPONumber
            //, int pPOrC, string pDeliveryOrderNumber, string pDeliveryDate, bool pIsDelivered, bool pIsReceivedFromShipper, int pConsigneeID2,
            //string pReleaseDate, string pExpectedDeparture, string pExpectedArrival
            //, string pBLDate, string pShippedOnBoardDate, string pFreightPayableAt, string pACIDNumber,
            //int pNumberOfOriginalBills
            //, string pCertificateNumber, string pCountryOfOrigin, string pInvoiceValue, int pCurrencyID,
            //string pBookingNumber, string pACIDNumberDetails, decimal pIMOClass, int pUNNumber, string pManifestPreConsignee = "", int pVesselID = 0, bool pPrintHouseConsignee = false, string pIsIMOHouse = "", int pOperationManID = -1
            //, int pStoreLocation = 0, string pBlStatus = "", int pForwarder = 0, int pQuotationRouteID = 0, int pPOT = 0, string pHouseContainerNumber = "", string pNotes1 = "", int pHouseStatus = 0, string pForm13Notes = "0", string pForm13Number = "0", string pBusinessUnit = "0", string pBusinessUnit2 = "0", int pShipmentType = 0, int pRoutingPickUpCountry = 0, int pRoutingPickUpCity = 0, int pTransportType = 0, string pReferenceNumber = "0" , string pPrintType = ""
        {
            Exception checkException = null;
            COperations objCOperations = new COperations();

            COperationPartners objCOperationPartners = new COperationPartners();
            CRoutings objCRoutings = new CRoutings();
            var MainCarraigeRoutingTypeID = 30;

            var constCustomerPartnerTypeID = 1;
            var constAgentPartnerTypeID = 2;

            var constShipperOperationPartnerTypeID = 1;
            var constConsigneeOperationPartnerTypeID = 2;
            var constConsignee2OperationPartnerTypeID = 3;
            var constNotify1OperationPartnerTypeID = 4;
            var constAgentOperationPartnerTypeID = 6;



            string pUpdateClause = "";
            string _MessageReturned = "";
            int _RowCount = 0;

            COperations objCOperationsBeforeUpdate = new COperations();
            objCOperationsBeforeUpdate.GetListPaging(999999, 1, "WHERE  ID =" + shipment_Update.pShipmentID, "ID", out _RowCount);

            CDefaults objCDefaults = new CDefaults();
            objCDefaults.GetListPaging(1, 1, "", "ID", out _RowCount);
            #region Cheque HouseNumber uniqueness
            COperations objCOperations_CheckUniqueness = new COperations();
            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "EGL" || objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "SUN")
                objCOperations_CheckUniqueness.GetListPaging(999999, 1, "WHERE HouseNumber IS NOT NULL AND HouseNumber<>N'' AND HouseNumber<>N'N/A' AND HouseNumber=N'" + shipment_Update.pHouseNumber + "' AND ID<>" + shipment_Update.pShipmentID, "ID", out _RowCount);
            if (objCOperations_CheckUniqueness.lstCVarOperations.Count > 0)
                _MessageReturned = "This house number already exists.";
            #endregion Cheque HouseNumber uniqueness


            COperations objCOperations_CheckUniquenessAll = new COperations();
            if (shipment_Update.pHouseNumber != "0" && (objCOperationsBeforeUpdate.lstCVarOperations.Count == 0 || objCOperationsBeforeUpdate.lstCVarOperations[0].HouseNumber != shipment_Update.pHouseNumber))
            {
                objCOperations_CheckUniquenessAll.GetListPaging(999999, 1, "WHERE HouseNumber IS NOT NULL AND HouseNumber<>N'' AND HouseNumber<>N'N/A' AND HouseNumber=N'" + shipment_Update.pHouseNumber + "' AND ID<>" + shipment_Update.pShipmentID, "ID", out _RowCount);
                if (objCOperations_CheckUniquenessAll.lstCVarOperations.Count > 0)
                    _MessageReturned = "This house number already exists.";
            }


            CvwDefaults objCvwDefaults = new CvwDefaults();
            objCvwDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);
            #region Check ACIDNumber Uiqueness UNF
            COperations objCOperations_CheckUniquenessACID = new COperations();
            objCOperations_CheckUniquenessACID.GetListPaging(999999, 1, "WHERE ACIDNumber='" + shipment_Update.pACIDNumber + "'", "ID", out _RowCount);
            if (objCvwDefaults.lstCVarvwDefaults[0].UnEditableCompanyName == "UNF" && objCOperationsBeforeUpdate.lstCVarOperations[0].ACIDNumber != shipment_Update.pACIDNumber && shipment_Update.pACIDNumber != "" && _RowCount > 0)
            {
                _MessageReturned = "This ACIDNumber (" + objCOperations_CheckUniquenessACID.lstCVarOperations[0].ACIDNumber + ") already exists.";
            }
            #endregion



            if (_MessageReturned == "")
            {
                pUpdateClause += " BranchID=" + (shipment_Update.pBranchID == 0 ? "NULL" : shipment_Update.pBranchID.ToString()) + " \n";
                //Salesman, MoveTypeID and POrC are mandatory, so 0 means the client did not supply a value
                //(unloaded/hidden combo) and never means "clear it": leave the stored value untouched.
                pUpdateClause += shipment_Update.pSalesmanID == 0 ? "" : ", SalesmanID=" + shipment_Update.pSalesmanID.ToString() + " \n";
                pUpdateClause += ", OpenDate='" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pOpenDate, 2) + "' \n";
                pUpdateClause += ", HouseNumber=" + (shipment_Update.pHouseNumber == "0" ? "NULL" : ("'" + shipment_Update.pHouseNumber + "'")) + " \n";
                pUpdateClause += ", POLCountryID=" + (shipment_Update.pPOLCountryID == 0 ? "NULL" : shipment_Update.pPOLCountryID.ToString()) + " \n";
                pUpdateClause += ", PickupCityID=" + (shipment_Update.pPickupCityID == 0 ? "NULL" : shipment_Update.pPickupCityID.ToString()) + " \n";
                pUpdateClause += ", POL=" + (shipment_Update.pPickupCityID == 0 ? "NULL" : shipment_Update.pPickupCityID.ToString()) + " \n";
                pUpdateClause += ", PODCountryID=" + (shipment_Update.pPODCountryID == 0 ? "NULL" : shipment_Update.pPODCountryID.ToString()) + " \n";
                pUpdateClause += ", DeliveryCityID=" + (shipment_Update.pDeliveryCityID == 0 ? "NULL" : shipment_Update.pDeliveryCityID.ToString()) + " \n";
                pUpdateClause += ", POD=" + (shipment_Update.pDeliveryCityID == 0 ? "NULL" : shipment_Update.pDeliveryCityID.ToString()) + " \n";
                pUpdateClause += ", ShipperID=" + (shipment_Update.pShipperID == 0 ? "NULL" : shipment_Update.pShipperID.ToString()) + " \n";
                pUpdateClause += ", ConsigneeID=" + (shipment_Update.pConsigneeID == 0 ? "NULL" : shipment_Update.pConsigneeID.ToString()) + " \n";
                pUpdateClause += ", AgentID=" + (shipment_Update.pAgentID == 0 ? "NULL" : shipment_Update.pAgentID.ToString()) + " \n";
                pUpdateClause += ", IncotermID=" + (shipment_Update.pIncotermID == 0 ? "NULL" : shipment_Update.pIncotermID.ToString()) + " \n";
                pUpdateClause += shipment_Update.pMoveTypeID == 0 ? "" : ", MoveTypeID=" + shipment_Update.pMoveTypeID.ToString() + " \n";
                pUpdateClause += ", Notes=" + (shipment_Update.pNotes == "0" ? "NULL" : ("N'" + shipment_Update.pNotes + "'")) + " \n";
                pUpdateClause += ", Notes2=" + (shipment_Update.pNotes1 == "0" ? "NULL" : ("N'" + shipment_Update.pNotes1 + "'")) + " \n";

                pUpdateClause += ", CommodityID=" + (shipment_Update.pCommodityID == 0 ? "NULL" : shipment_Update.pCommodityID.ToString()) + " \n";
                pUpdateClause += ", CustomerReference=" + (shipment_Update.pCustomerReference == "0" ? "NULL" : ("'" + shipment_Update.pCustomerReference + "'")) + " \n";
                pUpdateClause += ", SupplierReference=" + (shipment_Update.pSupplierReference == "0" ? "NULL" : ("'" + shipment_Update.pSupplierReference + "'")) + " \n";
                pUpdateClause += ", PONumber=" + (shipment_Update.pPONumber == "0" ? "NULL" : ("'" + shipment_Update.pPONumber + "'")) + " \n";
                pUpdateClause += shipment_Update.pPOrC == 0 ? "" : ", POrC=" + shipment_Update.pPOrC.ToString() + " \n";

                pUpdateClause += ", IsDelivered = " + (shipment_Update.pIsDelivered ? "1" : "0") + " \n";
                pUpdateClause += ", IsReceivedFromShipper = " + (shipment_Update.pIsReceivedFromShipper ? "1" : "0") + " \n";
                pUpdateClause += ", ConsigneeID2=" + (shipment_Update.pConsigneeID2 == 0 ? "NULL" : shipment_Update.pConsigneeID2.ToString()) + " \n";
                pUpdateClause += (shipment_Update.pReleaseDate == "01/01/1900" ? ", ReleaseDate = NULL " : ", ReleaseDate = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pReleaseDate, 2) + "'") + " \n";
                pUpdateClause += (shipment_Update.pBLDate == "01/01/1900" ? ", BLDate = NULL " : ", BLDate = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pBLDate, 2) + "'") + " \n";
                pUpdateClause += (shipment_Update.pShippedOnBoardDate == "01/01/1900" ? ", ShippedOnBoardDate = NULL " : ", ShippedOnBoardDate = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pShippedOnBoardDate, 2) + "'") + " \n";
                pUpdateClause += ", FreightPayableAt=" + (shipment_Update.pFreightPayableAt == "0" ? "NULL" : ("N'" + shipment_Update.pFreightPayableAt + "'")) + " \n";
                pUpdateClause += ", ACIDNumber=" + (shipment_Update.pACIDNumber == "0" ? "NULL" : ("N'" + shipment_Update.pACIDNumber + "'")) + " \n";
                pUpdateClause += ", ACIDDetails=" + (shipment_Update.pACIDNumberDetails == "0" ? "NULL" : ("N'" + shipment_Update.pACIDNumberDetails + "'")) + " \n";
                pUpdateClause += ", BookingNumber=" + (shipment_Update.pBookingNumber == "0" ? "NULL" : ("N'" + shipment_Update.pBookingNumber + "'")) + " \n";
                pUpdateClause += ", NumberOfOriginalBills=" + (shipment_Update.pNumberOfOriginalBills == 0 ? "NULL" : shipment_Update.pNumberOfOriginalBills.ToString()) + " \n";
                pUpdateClause += ", CertificateNumber=" + (shipment_Update.pCertificateNumber == "0" ? "NULL" : ("N'" + shipment_Update.pCertificateNumber + "'")) + " \n";
                pUpdateClause += ", CountryOfOrigin=" + (shipment_Update.pCountryOfOrigin == "0" ? "NULL" : ("N'" + shipment_Update.pCountryOfOrigin + "'")) + " \n";
                pUpdateClause += ", InvoiceValue=" + (shipment_Update.pInvoiceValue == "0" ? "NULL" : ("N'" + shipment_Update.pInvoiceValue + "'")) + " \n";
                pUpdateClause += ", CurrencyID=" + (shipment_Update.pCurrencyID == 0 ? "NULL" : shipment_Update.pCurrencyID.ToString()) + " \n";

                pUpdateClause += " , IMOClass = " + (shipment_Update.pIMOClass == Decimal.Zero ? " NULL " : shipment_Update.pIMOClass.ToString());
                pUpdateClause += " , UNNumber = " + (shipment_Update.pUNNumber == 0 ? " NULL " : shipment_Update.pUNNumber.ToString());
                pUpdateClause += " , VesselID = " + (shipment_Update.pVesselID == 0 ? " NULL " : shipment_Update.pVesselID.ToString());
                pUpdateClause += (shipment_Update.pOperationManID == -1 || shipment_Update.pOperationManID == 0) ? "" : (" , OperationManID = " + shipment_Update.pOperationManID.ToString());

                //pUpdateClause += pPOLCountryID == 0 ? "" : (" , POLCountryID = " + pPOLCountryID.ToString());
                //pUpdateClause += pPOL == 0 ? "" : (" , POL = " + pPOL.ToString());
                //pUpdateClause += pPODCountryID == 0 ? "" : (" , PODCountryID = " + pPODCountryID.ToString());
                //pUpdateClause += pPOD == 0 ? "" : (" , POD = " + pPOD.ToString());
                pUpdateClause += shipment_Update.pStoreLocation == 0 ? "" : " , StoreLocation = " + shipment_Update.pStoreLocation;
                pUpdateClause += shipment_Update.pBlStatus == "" ? "" : " , BlStatus = N'" + shipment_Update.pBlStatus + "'";
                pUpdateClause += shipment_Update.pForwarder == 0 ? ", ForwarderId = NULL" : " , ForwarderId = " + shipment_Update.pForwarder;
                pUpdateClause += shipment_Update.pQuotationRouteID == 0 ? "" : " , QuotationRouteID = " + shipment_Update.pQuotationRouteID;
                pUpdateClause += " , PrintHouseConsignee = " + (shipment_Update.pPrintHouseConsignee ? "1" : "0");

                if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF" && shipment_Update.pShipmentType > 0)
                {
                    pUpdateClause += " , ShipmentType = " + shipment_Update.pShipmentType;
                }
                if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF")
                {
                    pUpdateClause += " , ETAPOlAlarmStatus = " + shipment_Update.pRoutingPickUpCountry;
                    pUpdateClause += " , ATAPOLAlarmStatus = " + shipment_Update.pRoutingPickUpCity;
                    if (shipment_Update.pTransportType != 0)
                        pUpdateClause += ", TransportType=" + (shipment_Update.pTransportType == 0 ? "NULL" : shipment_Update.pTransportType.ToString()) + " \n";

                }

                //Note: According to Eng.Eslam Tarek to use IsFleet field to represent IsIMO for houses to avoid adding a new field to the operations table. 08/08/2024 (By Mustafa Mahmoud)
                if (shipment_Update.pIsIMOHouse != "" && shipment_Update.pIsIMOHouse != null)
                    pUpdateClause += " , IsFleet = " + shipment_Update.pIsIMOHouse;

                pUpdateClause += ", Form13Notes=" + (shipment_Update.pForm13Notes == "0" ? "NULL" : ("N'" + shipment_Update.pForm13Notes + "'")) + " \n";
                pUpdateClause += ", Form13Number=" + (shipment_Update.pForm13Number == "0" ? "NULL" : ("N'" + shipment_Update.pForm13Number + "'")) + " \n";
                pUpdateClause += ", BusinessUnit=" + (shipment_Update.pBusinessUnit == "0" ? "NULL" : ("N'" + shipment_Update.pBusinessUnit + "'")) + " \n";
                pUpdateClause += ", BusinessUnit2=" + (shipment_Update.pBusinessUnit2 == "0" ? "NULL" : ("N'" + shipment_Update.pBusinessUnit2 + "'")) + " \n";
                pUpdateClause += ", IATACode=" + (shipment_Update.pPrintType == "0" ? "NULL" : ("N'" + shipment_Update.pPrintType + "'")) + " \n";


                //pUpdateClause += " , ManifestPreConsignee = N'" + (pManifestPreConsignee == "" ? "" : pManifestPreConsignee.ToString() + "' ");
                pUpdateClause += " , ManifestPreConsignee = " + (string.IsNullOrEmpty(shipment_Update.pManifestPreConsignee) ? "NULL" : "N'" + shipment_Update.pManifestPreConsignee + "'") + " \n";

                pUpdateClause += shipment_Update.pPOT == 0 ? null : (" , POTID = " + shipment_Update.pPOT);
                pUpdateClause += " , HouseContainerNumber = " + (string.IsNullOrEmpty(shipment_Update.pHouseContainerNumber) ? "NULL" : "N'" + shipment_Update.pHouseContainerNumber + "'");
                if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF" && shipment_Update.pHouseStatus != 0)
                {
                    pUpdateClause += " , OperationStageID = " + shipment_Update.pHouseStatus;
                }

                pUpdateClause += ", ReferenceNumber=" + (shipment_Update.pReferenceNumber == "0" ? "NULL" : ("'" + shipment_Update.pReferenceNumber + "'")) + " \n";
                pUpdateClause += " WHERE ID=" + shipment_Update.pShipmentID.ToString() + " \n";
                checkException = objCOperations.UpdateList(pUpdateClause);
                #region Update Partners
                //Update Shipper

                int pPartnerIDShipper = 0;
                if (objCOperationsBeforeUpdate.lstCVarOperations.Count > 0 && objCOperationsBeforeUpdate.lstCVarOperations[0].ShipperID != 0)
                    pPartnerIDShipper = objCOperationsBeforeUpdate.lstCVarOperations[0].ShipperID;


                CvwInvoices objCvwShipperInvoices = new CvwInvoices();
                objCvwShipperInvoices.GetListPaging(1, 1, "Where OperationID= " + shipment_Update.pShipmentID + " And PartnerID=" + pPartnerIDShipper, "ID", out _RowCount);

                if (objCvwShipperInvoices.lstCVarvwInvoices.Count > 0 && shipment_Update.pShipperID != pPartnerIDShipper)
                {
                    CContacts objCContacts = new CContacts();//to save a contact by default
                    objCContacts.GetList(" WHERE PartnerTypeID = 1 AND PartnerID = " + shipment_Update.pShipperID.ToString());

                    COperationPartners objCOperationPartnersNew = new COperationPartners();
                    CVarOperationPartners objCVarOperationConsignee2Partner = new CVarOperationPartners();
                    objCVarOperationConsignee2Partner.ID = 0;
                    objCVarOperationConsignee2Partner.OperationID = shipment_Update.pShipmentID;
                    objCVarOperationConsignee2Partner.OperationPartnerTypeID = 1;
                    objCVarOperationConsignee2Partner.CustomerID = shipment_Update.pShipperID;
                    objCVarOperationConsignee2Partner.ContactID = (objCContacts.lstCVarContacts.Count > 0 ? objCContacts.lstCVarContacts[0].ID : 0);
                    objCVarOperationConsignee2Partner.IsOperationClient = false;
                    objCVarOperationConsignee2Partner.CreatorUserID = objCVarOperationConsignee2Partner.ModificatorUserID = WebSecurity.CurrentUserId;
                    objCVarOperationConsignee2Partner.CreationDate = objCVarOperationConsignee2Partner.ModificationDate = DateTime.Now;
                    objCOperationPartnersNew.lstCVarOperationPartners.Add(objCVarOperationConsignee2Partner);
                    checkException = objCOperationPartnersNew.SaveMethod(objCOperationPartnersNew.lstCVarOperationPartners);
                }
                else
                {



                    pUpdateClause = "CustomerID=" + (shipment_Update.pShipperID == 0 ? "NULL" : shipment_Update.pShipperID.ToString()) + "\n";
                    pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constCustomerPartnerTypeID + " and PartnerID=" + shipment_Update.pShipperID + ")" + "\n";
                    pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=" + constShipperOperationPartnerTypeID;
                    checkException = objCOperationPartners.UpdateList(pUpdateClause);

                }


                //Update Consignee

                int pPartnerID = 0;
                if (objCOperationsBeforeUpdate.lstCVarOperations.Count > 0 && objCOperationsBeforeUpdate.lstCVarOperations[0].ConsigneeID != 0)
                    pPartnerID = objCOperationsBeforeUpdate.lstCVarOperations[0].ConsigneeID;
                CvwInvoices objCvwInvoices = new CvwInvoices();
              //  objCvwInvoices.GetListPaging(1, 1, "Where OperationID= " + shipment_Update.pShipmentID + " And PartnerID=" + pPartnerID, "ID", out _RowCount);

                objCOperationPartners.GetList("Where OperationPartnerTypeID=2 AND OperationID= " + shipment_Update.pShipmentID + " And CustomerID= " + pPartnerID);
                if(objCOperationPartners.lstCVarOperationPartners.Count > 0)
                  objCvwInvoices.GetListPaging(1, 1, "Where IsApproved= 1 And OperationID= " + shipment_Update.pShipmentID + " And OperationPartnerID=" + objCOperationPartners.lstCVarOperationPartners[0].ID, "ID", out _RowCount);
            
                if (objCvwInvoices.lstCVarvwInvoices.Count > 0 && shipment_Update.pConsigneeID != pPartnerID)
                {
                    CContacts objCContacts = new CContacts();//to save a contact by default
                    objCContacts.GetList(" WHERE PartnerTypeID = 1 AND PartnerID = " + shipment_Update.pConsigneeID.ToString());

                    COperationPartners objCOperationPartnersNew = new COperationPartners();
                    CVarOperationPartners objCVarOperationConsignee2Partner = new CVarOperationPartners();
                    objCVarOperationConsignee2Partner.ID = 0;
                    objCVarOperationConsignee2Partner.OperationID = shipment_Update.pShipmentID;
                    objCVarOperationConsignee2Partner.OperationPartnerTypeID = 2;
                    objCVarOperationConsignee2Partner.CustomerID = shipment_Update.pConsigneeID;
                    objCVarOperationConsignee2Partner.ContactID = (objCContacts.lstCVarContacts.Count > 0 ? objCContacts.lstCVarContacts[0].ID : 0);
                    objCVarOperationConsignee2Partner.IsOperationClient = false;
                    objCVarOperationConsignee2Partner.CreatorUserID = objCVarOperationConsignee2Partner.ModificatorUserID = WebSecurity.CurrentUserId;
                    objCVarOperationConsignee2Partner.CreationDate = objCVarOperationConsignee2Partner.ModificationDate = DateTime.Now;
                    objCOperationPartnersNew.lstCVarOperationPartners.Add(objCVarOperationConsignee2Partner);
                    checkException = objCOperationPartnersNew.SaveMethod(objCOperationPartnersNew.lstCVarOperationPartners);

                }
                else
                {
                    pUpdateClause = "CustomerID=" + (shipment_Update.pConsigneeID == 0 ? "NULL" : shipment_Update.pConsigneeID.ToString()) + "\n";
                    pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constCustomerPartnerTypeID + " and PartnerID=" + shipment_Update.pConsigneeID + ")" + "\n";
                    pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=" + constConsigneeOperationPartnerTypeID;
                    checkException = objCOperationPartners.UpdateList(pUpdateClause);
                }
                // insert Consignee2 if not exist
                COperationPartners objCOperationPartnersOld = new COperationPartners();
                int NumberOfConsignee2 = 0;
                objCOperationPartnersOld.GetListPaging(1, 1, "WHERE OperationPartnerTypeID=3 AND OperationID=" + shipment_Update.pShipmentID.ToString(), "ID", out NumberOfConsignee2);

                if (NumberOfConsignee2 != 1)
                {
                    //to save a contact by default //PartnerTypeID = 1 for Customer
                    CContacts objCContacts = new CContacts();//to save a contact by default
                    objCContacts.GetList(" WHERE PartnerTypeID = 1 AND PartnerID = " + shipment_Update.pConsigneeID2.ToString());

                    COperationPartners objCOperationPartnersNew = new COperationPartners();
                    CVarOperationPartners objCVarOperationConsigneePartner = new CVarOperationPartners();
                    objCVarOperationConsigneePartner.ID = 0;
                    objCVarOperationConsigneePartner.OperationID = shipment_Update.pShipmentID;
                    objCVarOperationConsigneePartner.OperationPartnerTypeID = 3;
                    objCVarOperationConsigneePartner.CustomerID = shipment_Update.pConsigneeID2;
                    objCVarOperationConsigneePartner.ContactID = (objCContacts.lstCVarContacts.Count > 0 ? objCContacts.lstCVarContacts[0].ID : 0);
                    objCVarOperationConsigneePartner.IsOperationClient = false;
                    objCVarOperationConsigneePartner.CreatorUserID = objCVarOperationConsigneePartner.ModificatorUserID = WebSecurity.CurrentUserId;
                    objCVarOperationConsigneePartner.CreationDate = objCVarOperationConsigneePartner.ModificationDate = DateTime.Now;
                    objCOperationPartnersNew.lstCVarOperationPartners.Add(objCVarOperationConsigneePartner);
                    checkException = objCOperationPartnersNew.SaveMethod(objCOperationPartnersNew.lstCVarOperationPartners);
                }

                // insert Forwarder if not exist
                bool IsForwarderExists = false;
                objCOperationPartnersOld.GetList("WHERE OperationPartnerTypeID=220 AND OperationID=" + shipment_Update.pShipmentID.ToString());
                IsForwarderExists = objCOperationPartnersOld.lstCVarOperationPartners.Count > 0;

                if (!IsForwarderExists)
                {
                    COperationPartners objCOperationPartnersNew = new COperationPartners();
                    CVarOperationPartners objCVarOperationForwarderPartner = new CVarOperationPartners();
                    objCVarOperationForwarderPartner.ID = 0;
                    objCVarOperationForwarderPartner.OperationID = shipment_Update.pShipmentID;
                    objCVarOperationForwarderPartner.OperationPartnerTypeID = 220;
                    objCVarOperationForwarderPartner.CustomerID = shipment_Update.pForwarder;
                    objCVarOperationForwarderPartner.IsOperationClient = false;
                    objCVarOperationForwarderPartner.CreatorUserID = objCVarOperationForwarderPartner.ModificatorUserID = WebSecurity.CurrentUserId;
                    objCVarOperationForwarderPartner.CreationDate = objCVarOperationForwarderPartner.ModificationDate = DateTime.Now;
                    objCOperationPartnersNew.lstCVarOperationPartners.Add(objCVarOperationForwarderPartner);
                    checkException = objCOperationPartnersNew.SaveMethod(objCOperationPartnersNew.lstCVarOperationPartners);
                }
                else
                {
                    //Update Consignee
                    pUpdateClause = "CustomerID=" + (shipment_Update.pForwarder == 0 ? "NULL" : shipment_Update.pForwarder.ToString()) + "\n";
                    pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constCustomerPartnerTypeID + " and PartnerID=" + shipment_Update.pForwarder + ")" + "\n";
                    pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=220";
                    checkException = objCOperationPartners.UpdateList(pUpdateClause);
                }


                //Update Consignee2
                pUpdateClause = "CustomerID=" + (shipment_Update.pConsigneeID2 == 0 ? "NULL" : shipment_Update.pConsigneeID2.ToString()) + "\n";
                pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constCustomerPartnerTypeID + " and PartnerID=" + shipment_Update.pConsigneeID2 + ")" + "\n";
                pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=" + constConsignee2OperationPartnerTypeID;
                checkException = objCOperationPartners.UpdateList(pUpdateClause);


                COperationPartners objCOperationPartnersAgentOld = new COperationPartners();

                bool IsAgentExists = false;
                objCOperationPartnersAgentOld.GetList("WHERE OperationPartnerTypeID=6 AND OperationID=" + shipment_Update.pShipmentID.ToString());
                IsAgentExists = objCOperationPartnersAgentOld.lstCVarOperationPartners.Count > 0;
                if (!IsAgentExists)
                {
                    COperationPartners objCOperationPartnersNew = new COperationPartners();
                    CVarOperationPartners objCVarOperationAgentPartner = new CVarOperationPartners();
                    objCVarOperationAgentPartner.ID = 0;
                    objCVarOperationAgentPartner.OperationID = shipment_Update.pShipmentID;
                    objCVarOperationAgentPartner.OperationPartnerTypeID = 6;
                    objCVarOperationAgentPartner.IsOperationClient = false;
                    objCVarOperationAgentPartner.AgentID = shipment_Update.pAgentID;
                    objCVarOperationAgentPartner.CreatorUserID = objCVarOperationAgentPartner.ModificatorUserID = WebSecurity.CurrentUserId;
                    objCVarOperationAgentPartner.CreationDate = objCVarOperationAgentPartner.ModificationDate = DateTime.Now;
                    objCOperationPartnersNew.lstCVarOperationPartners.Add(objCVarOperationAgentPartner);
                    checkException = objCOperationPartnersNew.SaveMethod(objCOperationPartnersNew.lstCVarOperationPartners);
                }
                else
                {
                    //Update Agent
                    pUpdateClause = "AgentID=" + (shipment_Update.pAgentID == 0 ? "NULL" : shipment_Update.pAgentID.ToString()) + "\n";
                    pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constAgentPartnerTypeID + " and PartnerID=" + shipment_Update.pAgentID + ")" + "\n";
                    pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=" + constAgentOperationPartnerTypeID;
                    checkException = objCOperationPartners.UpdateList(pUpdateClause);

                }
                //Update Notify
                pUpdateClause = "CustomerID=" + (shipment_Update.pNotifyID == 0 ? "NULL" : shipment_Update.pNotifyID.ToString()) + "\n";
                pUpdateClause += ", ContactID=(select min(ID) from Contacts where PartnerTypeID=" + constCustomerPartnerTypeID + " and PartnerID=" + shipment_Update.pNotifyID + ")" + "\n";
                pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND OperationPartnerTypeID=" + constNotify1OperationPartnerTypeID;
                checkException = objCOperationPartners.UpdateList(pUpdateClause);
                #endregion Update Partners

                #region Update MainRoute
                pUpdateClause = "DeliveryOrderNumber=" + (shipment_Update.pDeliveryOrderNumber == "0" ? "NULL" : ("N'" + shipment_Update.pDeliveryOrderNumber.ToString() + "'")) + "\n";
                pUpdateClause += shipment_Update.pDeliveryDate == ", DeliveryDate=NULL" ? "" : (", DeliveryDate='" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pDeliveryDate, 2)) + "' \n";
                pUpdateClause += shipment_Update.pExpectedDeparture == null || shipment_Update.pExpectedDeparture == "0" ? "" : ", ExpectedDeparture = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pExpectedDeparture, 2) + "' \n";
                pUpdateClause += shipment_Update.pExpectedArrival == null || shipment_Update.pExpectedArrival == "0" ? "" : ", ExpectedArrival = '" + Forwarding.MvcApp.Helpers.DateFunctionsController.GetYYYYMMDDFormat(shipment_Update.pExpectedArrival, 2) + "' \n";

                pUpdateClause += " WHERE OperationID=" + shipment_Update.pShipmentID.ToString() + " AND RoutingTypeID=" + MainCarraigeRoutingTypeID.ToString();
                checkException = objCRoutings.UpdateList(pUpdateClause);

                if (checkException == null)
                {
                    //checkException = SaveOperationLog(pShipmentID);
                }
                #endregion Update MainRoute
            } //if (_MessageReturned == "")
            return new object[] {
                checkException == null ? true : false
                , _MessageReturned //pData[1]
            };
        }

        public Exception SaveOperationLog(long pOperationID)
        {
            Exception checkException;
            int TotalRecords = 0;

            var UpdatedHouse = new CvwOperations();
            UpdatedHouse.GetListPaging(9, 1, " WHERE ID= " + pOperationID.ToString(), " ID ", out TotalRecords);
            var obj = UpdatedHouse.lstCVarvwOperations[0];
            checkException = Logging.Save<CVarvwOperations>(ref obj, Convert.ToInt32(UpdatedHouse.lstCVarvwOperations[0].ID));

            return checkException;
        }

