                    if (checkException == null)
                    {
                        var masterContainer = new COperationContainersAndPackages();
                        checkException = masterContainer.GetList($" where OperationID = {pMasterOperationID} ");

                        var houseContainer = new COperationContainersAndPackages();
                        checkException = houseContainer.DeleteList($" where OperationID = {pHouseID} ");
