                            //        Volume = item.Volume,
                            //        VolumetricWeight = item.VolumetricWeight,
                            //        NetWeight = item.NetWeight,
                            //        NetWeightTON = item.NetWeightTON,
                            //        GrossWeight = item.GrossWeight,
                            //        GrossWeightTON = item.GrossWeightTON,
                            //        ChargeableWeight = item.ChargeableWeight,
                            //        DescriptionOfGoods = item.DescriptionOfGoods,
                            //        NumberOfPackagesOnContainer = item.NumberOfPackagesOnContainer,
                            //        CreatorUserID = WebSecurity.CurrentUserId,
                            //        ModificatorUserID = WebSecurity.CurrentUserId,
                            //        CreationDate = DateTime.Now,
                            //        ModificationDate = DateTime.Now,
                            //        ExitDate = item.ExitDate,
                            //        GateOutDate = item.GateOutDate,
                            //        LoadingDate = item.LoadingDate,
                            //        ReturnDate = item.ReturnDate,
                            //        YardInDate = item.YardInDate,
                            //        YardOutDate = item.YardOutDate,
                            //        StuffingDate = item.StuffingDate,
                            //        TankCertExpiryDate = item.TankCertExpiryDate,
