                            //    Common.Common.ReplaceNull(houseContainer.lstCVarOperationContainersAndPackages[houseContainer.lstCVarOperationContainersAndPackages.Count - 1]);
                        }
                        //checkException = houseContainer.SaveMethod(houseContainer.lstCVarOperationContainersAndPackages);

                        #region PlaceOn
                        if (checkException == null)
                        {
                            var housePlaceOn = new COperationContainersAndPackagesPlacedOn();
                            foreach (var item in masterContainer.lstCVarOperationContainersAndPackages)
                            {
                                if (item.ID == 0) continue;
                                housePlaceOn.lstCVarOperationContainersAndPackagesPlacedOn.Add(new CVarOperationContainersAndPackagesPlacedOn
