                checkException = objCOperations.GetItem(pShipmentID);
            if (objCOperations.lstCVarOperations.Count > 0)
                pConnectedToOperationID = objCOperations.lstCVarOperations[0].MasterOperationID; //of not connected then 0
            else //new Shipment to Connected direclty
                pConnectedToOperationID = pMasterOperationID;

            COperationContainersAndPackages objCOperationContainersAndPackages = new COperationContainersAndPackages();
            objCOperationContainersAndPackages.GetListPaging(10000, 1, "WHERE OperationID=" + pShipmentID.ToString() + " OR ID IN (SELECT OperationContainersAndPackagesID FROM OperationContainersAndPackagesPlacedOn WHERE OperationID=" + pShipmentID.ToString() + ")", "ID", out _RowCount);

            CPackageTypes objCPackageTypes = new CPackageTypes();
            objCPackageTypes.GetList("ORDER BY Name");

            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var AirportsListAllData = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "select ID,Name from Ports WHERE IsAir = 1"
