            var AirportsList = AirportsListAllData.Select(a => new
            {
                ID = a.ID,
                Name = a.Name
            }).ToList();


            CPorts objCPortOfDestination = new CPorts(); //Port of destination
            CPorts objCPortOfPickup = new CPorts(); //Port of destination
            CCustomizedDBCall objCPortOfTransiet = new CCustomizedDBCall();
            var POT = objCPortOfTransiet.ExecuteQuery_ListOfObjects("SELECT ID , Name FROM PORTS ORDER BY Name", typeof(CVarPorts)).Cast<CVarPorts>().ToList();
            var POTransiet = POT.Select(p => new
            {
                ID = p.ID,
                NAME = p.Name
            }).ToList();
            if (pShipmentID == 0)
            {
                if (pMasterOperationID != 0)
                {
                    objCPortOfDestination.GetList("WHERE CountryID=" + objCOperationsMaster.lstCVarOperations[0].PODCountryID
                    + (pIsAWB ? " AND IsAir=1 " : ""));
                    objCPortOfPickup.GetList("WHERE CountryID=" + objCOperationsMaster.lstCVarOperations[0].POLCountryID
                        + (pIsAWB ? " AND IsAir=1 " : ""));
                }
                else
                {
                    objCPortOfDestination.GetList("WHERE 1=1"
                        + (pIsAWB ? " AND IsAir=1 " : ""));
                    objCPortOfPickup.GetList("WHERE 1=1"
                        + (pIsAWB ? " AND IsAir=1 " : ""));
                }

            }
            else if (pShipmentID > 0)
            {
                int PickupCountryID = 0;
                objCPortOfDestination.GetList("WHERE CountryID=" + (objCOperations.lstCVarOperations[0].DeliveryCountryID == 0 ? objCOperations.lstCVarOperations[0].PODCountryID : objCOperations.lstCVarOperations[0].DeliveryCountryID)
                    + (pIsAWB ? " AND IsAir=1 " : ""));
                if (objCOperations.lstCVarOperations[0].PickupCityID != 0)
                {
                    CPorts objCPorts = new CPorts();
                    objCPorts.GetItem(objCOperations.lstCVarOperations[0].PickupCityID);
                    PickupCountryID = objCPorts.lstCVarPorts.Count > 0 ? objCPorts.lstCVarPorts[0].CountryID : 0;
                }
                objCPortOfPickup.GetList("WHERE CountryID=" + (PickupCountryID == 0 ? objCOperations.lstCVarOperations[0].POLCountryID : PickupCountryID)
                    + (pIsAWB ? " AND IsAir=1 " : ""));
            }
            else if (pIsAWB && pDefaultCountryID != 0) //new AWB house
                objCPortOfDestination.GetList("WHERE CountryID=" + pDefaultCountryID.ToString() + " AND IsAir=1 ");

            CvwOperationContainersAndPackages objContainers = new CvwOperationContainersAndPackages();//get containers only if its connected to the master
            //objContainers.GetListPaging(1000, 1, "WHERE OperationID=" + pConnectedToOperationID, "ContainerTypeCode, ContainerNumber", out _RowCount);
            objContainers.GetListPaging(1000, 1, "WHERE OperationID=" + pConnectedToOperationID, "ID", out _RowCount);

            COperationPartners objCOperationPartners = new COperationPartners();
            objCOperationPartners.GetList("WHERE OperationID=" + pShipmentID + " AND OperationPartnerTypeID=" + constNotify1OperationPartnerTypeID);
            if (objCOperationPartners.lstCVarOperationPartners.Count > 0)
                pNotifyID = objCOperationPartners.lstCVarOperationPartners[0].CustomerID;

            CRoutings objCRoutings = new CRoutings();
            objCRoutings.GetListPaging(1000, 1, "WHERE OperationID=" + pShipmentID + " AND RoutingTypeID=" + MainCarraigeRoutingTypeID, "ID", out _RowCount);

            CAirlines objCAirline = new CAirlines(); //Port of destination
            checkException = objCAirline.GetListPaging(100000, 1, "WHERE 1=1 ", "Name", out _RowCount);

            CAirlines objCAirlineAIR = new CAirlines();
            var AirportsLineID = objCCustomizedDBCall.CallStringFunction("select AirlineID from vwRoutings where OperationID=" + pShipmentID);

            var AirportsLine = objCCustomizedDBCall.CallStringFunction("select Name from Airlines where id=" + AirportsLineID);


            CVessels objCVessels = new CVessels();
            objCVessels.GetList("Where 1=1");
            if (pMasterOperationID != 0)
            {
                if (objCOperationsMaster.lstCVarOperations[0].TransportType == 2)
                { //(pIsAWB) {
                    //objCvwPayables.GetListPaging(999999, 1, " WHERE OperationID = " + pShipmentID.ToString() /* AND IsDeleted = 0 */, "ID"/*"ChargeTypeName"*/, out _RowCount);   //it is disabled in js .. no need to get it here
                    if (objCOperations.lstCVarOperations.Count > 0)
                    {
                        objMbStck.GetList(" where id=" + objCOperations.lstCVarOperations[0].MAWBStockID);
                    }
                }
            }

            int CancelledQuoteAndOperStageID = 110;
            bool pIsOperationClosed = false;
            if (objCOperations.lstCVarOperations.Count > 0)
            {
                pIsOperationClosed = (objCOperations.lstCVarOperations[0].CloseDate < DateTime.Now && objCOperations.lstCVarOperations[0].OperationStageID != CancelledQuoteAndOperStageID);//2nd condition coz with time closedate passes but the operation is still cancelled
            }


            CUsers objCUsers = new CUsers();
