                objCUsers.GetList(" Where IsNull(CustomerID , 0) = 0 AND IsNull( (SELECT COUNT(us.ID) FROM dbo.UserSalesmen AS us WHERE us.UserID = " + CurrentUserID + " AND us.SalesManID = dbo.Users.ID  ) , 0 ) > 0 ORDER BY Name");
            else
                objCUsers.GetList(" where IsNull(CustomerID , 0) = 0 AND 1 = 1 ORDER BY Name");

            var pUserList = objCUsers.lstCVarUsers.Select(s => new
            {
                ID = s.ID
                                ,
                Name = s.Name
                                ,
                IsSalesman = s.IsSalesman
            }).ToList();

            var firstHouseId = 0L;
            if (pMasterOperationID > 0)
            {
                var firstHouse = new COperations();
                firstHouse.GetList($" where MasterOperationID = {pMasterOperationID} Order By ID Asc");
                firstHouseId = firstHouse.lstCVarOperations.Count > 0 ? firstHouse.lstCVarOperations[0].ID : 0;
            }

            //********************************************************
            CWH_Warehouse objCWareHouse = new CWH_Warehouse();
            checkException = objCWareHouse.GetListPaging(99999999, 1, "WHERE 1=1", "ID", out _RowCount);

