            {
                ID = w.ID,
                Name = w.Name
            }).ToList();
            //CCustomers objCCustomers = new CCustomers();
            //checkException = objCCustomers.GetListPaging(99999999, 1, "WHERE 1=1", "ID", out _RowCount);
            //var pCustomers = objCCustomers.lstCVarCustomers.Select(c => new
            //{
            //    ID = c.ID,
            //    Name = c.Name
            //}).ToList();
            //***********************************************************
            //Getting Invoices related to master operation
            CvwInvoices objCvwInvoices = new CvwInvoices();
            objCvwInvoices.GetList("WHERE OperationID = " + pShipmentID + " AND ChildInvoiceID IS NULL");
            var pInvoiceList = objCvwInvoices.lstCVarvwInvoices.Select(x => new
            {
                ID = x.ID,
                Name = $"{x.InvoiceNumber} / {x.InvoiceTypeName}"
            }).ToList();

            CUsers CobjUsers = new CUsers();
            CobjUsers.GetListPaging(99999, 1, "WHERE 1=1", "ID", out _RowCount);
            var USERS = CobjUsers.lstCVarUsers.Select(U => new
            {
                ID = U.ID,
                Name = U.Name
            }).ToList();

            #region Getting crm Quotation routes
            CcrmUserSalesmen objCcrmUserSalesmen = new CcrmUserSalesmen();
            objCcrmUserSalesmen.GetList("WHERE UserID = " + WebSecurity.CurrentUserId);
            var UserSalesmenIDs = string.Join(",", objCcrmUserSalesmen.lstCVarcrmUserSalesmen
                .Select(x => x.SalesmanID)
                .ToList());
            CcrmUserServices objCcrmUserServices = new CcrmUserServices();
            objCcrmUserServices.GetList("WHERE UserID = " + WebSecurity.CurrentUserId);
            var UserServicesIDs = string.Join(",", objCcrmUserServices.lstCVarcrmUserServices
                .Select(x => x.ServiceID)
                .ToList());
            //*******************************************************************************
            string[] MescoCompanies = new string[5] { "MES", "SAC", "GLO", "EUR", "ALT" };
            bool IsMescoCompany = MescoCompanies.Contains(pUnEditableCompanyName);
            List<CVarvwQuotationRoute> pQuotationRouteList = new List<CVarvwQuotationRoute>();
            dynamic SimplifiedQRList;
            if (IsMescoCompany || pUnEditableCompanyName == "UNF")
            {
                pQuotationRouteList = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"SELECT ID,Code FROM vwQuotationRoute WHERE ShipmentType = 2 AND DirectionType = {objCOperationsMaster.lstCVarOperations[0].DirectionType} AND SalesmanID IN ({(UserSalesmenIDs == "" ? "0" : UserSalesmenIDs)}) AND ServiceID IN ({(UserServicesIDs == "" ? "0" : UserServicesIDs)}) AND ID NOT IN (SELECT QuotationRouteID FROM Operations WHERE QuotationRouteID IS NOT NULL AND ID <> {pShipmentID})"
                         , typeof(CVarvwQuotationRoute))
                         .Cast<CVarvwQuotationRoute>()
                         .ToList();
                SimplifiedQRList = pQuotationRouteList.Select(qr => new
                {
                    ID = qr.ID,
                    Code = qr.Code
                }).ToList();
            } else
            {
                SimplifiedQRList = pQuotationRouteList;
            }
            #endregion Getting crm Quotation routes

            CQuotationRoute objSelectedQR = new CQuotationRoute();
            if (objCOperations.lstCVarOperations.Count == 1)
                objSelectedQR.GetItem(objCOperations.lstCVarOperations[0].QuotationRouteID);
            string SelectedQR;
            if (objSelectedQR.lstCVarQuotationRoute.Count == 1)
            {
                SelectedQR = objSelectedQR.lstCVarQuotationRoute[0].Code;
            } else
            {
                SelectedQR = "";
            }

            CCustomers PreSelectedCustomers = new CCustomers();
            string ConsigneeName = "";
            string Consignee2Name = "";
            string NotifyName = "";
            string ShipperName = "";
            string ForwarderName = "";
            string ConsigneeAddress = "";
            string ConsigneeTelAndFax = "";
            string ShipperAddress = "";
            string ShipperTelAndFax = "";
            string NotifyAddress = "";
            string NotifyTelAndFax = "";
            string AirlinePrefix = "";
            string POLCode = "";
            if (objCOperations.lstCVarOperations.Count == 1)
            {
                Exception ex = PreSelectedCustomers.GetItem(objCOperations.lstCVarOperations[0].ConsigneeID);
                if (ex == null && PreSelectedCustomers.lstCVarCustomers.Count == 1)
                {
                    ConsigneeName = PreSelectedCustomers.lstCVarCustomers[0].Name;
                    ConsigneeAddress = PreSelectedCustomers.lstCVarCustomers[0].Address;
                    ConsigneeTelAndFax = PreSelectedCustomers.lstCVarCustomers[0].PhonesAndFaxes;
                }
                ex = PreSelectedCustomers.GetItem(objCOperations.lstCVarOperations[0].ConsigneeID2);
                if (ex == null && PreSelectedCustomers.lstCVarCustomers.Count == 1)
                    Consignee2Name = PreSelectedCustomers.lstCVarCustomers[0].Name;
                ex = PreSelectedCustomers.GetItem(objCOperations.lstCVarOperations[0].ShipperID);
                if (ex == null && PreSelectedCustomers.lstCVarCustomers.Count == 1)
                {
                    ShipperName = PreSelectedCustomers.lstCVarCustomers[0].Name;
                    ShipperAddress = PreSelectedCustomers.lstCVarCustomers[0].Address;
                    ShipperTelAndFax = PreSelectedCustomers.lstCVarCustomers[0].PhonesAndFaxes;
                }
                ex = PreSelectedCustomers.GetItem(pNotifyID);
                if (ex == null && PreSelectedCustomers.lstCVarCustomers.Count == 1)
                {
                    NotifyName = PreSelectedCustomers.lstCVarCustomers[0].Name;
                    NotifyAddress = PreSelectedCustomers.lstCVarCustomers[0].Address;
                    NotifyTelAndFax = PreSelectedCustomers.lstCVarCustomers[0].PhonesAndFaxes;
                }
                ex = PreSelectedCustomers.GetItem(objCOperations.lstCVarOperations[0].ForwarderId);
                if (ex == null && PreSelectedCustomers.lstCVarCustomers.Count == 1)
                    ForwarderName = PreSelectedCustomers.lstCVarCustomers[0].Name;
            }
            if (objCOperations.lstCVarOperations.Count == 1 && objCOperations.lstCVarOperations[0].TransportType == 2)
            {
                CAirlines objCAirlines = new CAirlines();
                Exception ex2 = objCAirlines.GetItem(objCOperations.lstCVarOperations[0].AirlineID);
                if (ex2 == null && objCAirlines.lstCVarAirlines.Count == 1)
                    AirlinePrefix = objCAirlines.lstCVarAirlines[0].Prefix;

                CPorts objCPorts = new CPorts();
                ex2 = objCPorts.GetItem(objCOperations.lstCVarOperations[0].POL);
                if (ex2 == null && objCPorts.lstCVarPorts.Count == 1)
                    POLCode = objCPorts.lstCVarPorts[0].Code;
            }
            CSalesmen objCSalesmen = new CSalesmen();
            objCSalesmen.GetList("WHERE 1=1");
            var MescoSalesmen = objCSalesmen.lstCVarSalesmen.Select(s => new
            {
                ID = s.ID,
                Name = s.NAME
            }).ToList();

            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new object[] {
                pShipmentID > 0 ? serializer.Serialize(objCOperations.lstCVarOperations[0]) : null //pData[0]
                , null /*serializer.Serialize(objCvwCustomersWithMinimalColumns.lstCVarvwCustomersWithMinimalColumns)*/ //pData[1]
                , null /*serializer.Serialize(objCAgents.lstCVarvwAgentsForCombo)*/ //pData[2]
                , serializer.Serialize(objCOperationContainersAndPackages.lstCVarOperationContainersAndPackages) //pData[3]
                , serializer.Serialize(objCPackageTypes.lstCVarPackageTypes) //pData[4]
                , serializer.Serialize(objCPortOfDestination.lstCVarPorts) //pData[5]
                , serializer.Serialize(objContainers.lstCVarvwOperationContainersAndPackages) //pData[6]
                , pNotifyID //pData[7]
                , objCRoutings.lstCVarRoutings.Count > 0 ? serializer.Serialize(objCRoutings.lstCVarRoutings[0]) : null  //pData[7]
                , serializer.Serialize(objCAirline.lstCVarAirlines) //pData[9]
                , pShipmentID > 0 ? serializer.Serialize(objCvwPayables.lstCVarvwPayables) : null //pData[10]
                , serializer.Serialize(objMbStck.lstCVarvwMAWBStock) //pData[11]
                , serializer.Serialize(objCPortOfPickup.lstCVarPorts) //pData[12]
                , serializer.Serialize(objCCountries.lstCVarCountries) //pData[13]
                , serializer.Serialize(Incoterms) //pData[14]
                , serializer.Serialize(MoveTypes) //pData[15]
                , serializer.Serialize(FreightTypes) //pData[16]
                , pIsOperationClosed //pData[17]
                , serializer.Serialize(objCVessels.lstCVarVessels) //pData[18]
                , serializer.Serialize(pUserList) //pData[19]
                , serializer.Serialize(AirportsList) //pData[20]
                , firstHouseId //pData[21]
                ,serializer.Serialize(pWareHouseList) //pData[22]
                ,null/*serializer.Serialize(pCustomers)*/ //pData[23]
                ,serializer.Serialize(pInvoiceList) //pData[24]
                ,serializer.Serialize(SimplifiedQRList) //pData[25]
                ,serializer.Serialize(POTransiet) //pData[26]
                ,serializer.Serialize(USERS) // pData[27]
                ,pShipmentID > 0 ? SelectedQR : null //pData[28]
                ,pShipmentID > 0 ? ConsigneeName : null //pData[29]
                ,pShipmentID > 0 ? Consignee2Name : null //pData[30]
                ,pShipmentID > 0 ? NotifyName : null //pData[31]
                ,pShipmentID > 0 ? ShipperName : null //pData[32]
                ,pShipmentID > 0 ? serializer.Serialize(MescoSalesmen) : null //pData[33]
                ,pShipmentID > 0 ? ForwarderName : null //pData[34]
                ,ConsigneeAddress //pData[35]
                ,ConsigneeTelAndFax //pData[36]
                ,ShipperAddress //pData[37]
                ,ShipperTelAndFax //pData[38]
                ,NotifyAddress //pData[39]
                ,NotifyTelAndFax //pData[40]
                ,AirlinePrefix //pData[41]
                ,POLCode //pData[42]
                ,AirportsLine //pDate[43]
            };
        }

