        [HttpGet]
        public object GetQuotationRouteList(string pSearch, string pUnEditableCompanyName, int pShipmentID, byte pMasterDirectionType)
        {
            #region Getting crm Quotation routes
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();

            var UserSalesmen = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
    $"select SalesmanID from crmUserSalesmen WHERE UserID = {WebSecurity.CurrentUserId}"
    , typeof(CVarcrmUserSalesmen)).Cast<CVarcrmUserSalesmen>().ToList();
            var UserSalesmenIDs = string.Join(",", UserSalesmen.Select(x => x.SalesmanID).ToList());

            var UserServices = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
$"select ServiceID from crmUserServices WHERE UserID = {WebSecurity.CurrentUserId}"
, typeof(CVarcrmUserServices)).Cast<CVarcrmUserServices>().ToList();
            var UserServicesIDs = string.Join(",", UserServices.Select(x => x.ServiceID).ToList());

            //*******************************************************************************
            string[] MescoCompanies = new string[5] { "MES", "SAC", "GLO", "EUR", "ALT" };
            bool IsMescoCompany = MescoCompanies.Contains(pUnEditableCompanyName);
            List<CVarvwQuotationRoute> pQuotationRouteList = new List<CVarvwQuotationRoute>();
            if (IsMescoCompany || pUnEditableCompanyName == "UNF")
            {
                pQuotationRouteList = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"SELECT ID,Code FROM vwQuotationRoute WHERE ShipmentType = 2 AND DirectionType = {pMasterDirectionType} AND SalesmanID IN ({(UserSalesmenIDs == "" ? "0" : UserSalesmenIDs)}) AND ServiceID IN ({(UserServicesIDs == "" ? "0" : UserServicesIDs)}) AND ID NOT IN (SELECT QuotationRouteID FROM Operations WHERE QuotationRouteID IS NOT NULL AND ID <> {pShipmentID}) {pSearch}"
                         , typeof(CVarvwQuotationRoute))
                         .Cast<CVarvwQuotationRoute>()
                         .ToList();
            }
            #endregion Getting crm Quotation routes

            JavaScriptSerializer serializer = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
            return serializer.Serialize(pQuotationRouteList);
        }

