        [HttpGet, HttpPost]
        public object[] HoldUnHoldBill(Int32 pBillID, string pIsHold, string pHoldReason)
        {
            string _ReturnedMessage = "";

            Exception checkException = null;
            COperations objCOperations = new COperations();
            bool IsHold = Convert.ToBoolean(pIsHold);
            string UpdateStr = "";

            pHoldReason = pHoldReason == null ? "" : pHoldReason;

            if (IsHold)
            {
                UpdateStr = " IsHold = 0,HoldReason='" + pHoldReason.Trim() + "' WHERE ID=" + pBillID;
            }
            else
            {
                UpdateStr = " IsHold = 1,HoldReason='" + pHoldReason.Trim() + "' WHERE ID=" + pBillID;
            }
            checkException = objCOperations.UpdateList(UpdateStr);

            if (checkException == null)
            {
                CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
                objCCustomizedDBCall.SP_HoldTrans_Log("SP_HoldTransactionLog", WebSecurity.CurrentUserId, "Bill", pBillID, (IsHold ? "UH" : "H"), pHoldReason);
            }
            else
            {
                _ReturnedMessage = "Error occurred while changing status";
            }

            return new object[]
            {
                _ReturnedMessage
            };
        }



