        [HttpPost]
        public object[] NafezaValidateACID([FromBody] ValidateACIDDTO ValidateACIDDTO)
        {
            var checkExcpetion = new Exception();
            COperations objCOperations = new COperations();
            checkExcpetion = objCOperations.UpdateList("ACIDNumber = N'" + ValidateACIDDTO.pACIDNumber + "' WHERE ID = " + ValidateACIDDTO.pShipmentID);
            COperationNafeza CheckIfThereData = new COperationNafeza();
            string UpdateClause = "";

            CheckIfThereData.GetList($"where operationID ={ValidateACIDDTO.pShipmentID}");
            if (CheckIfThereData.lstCVarOperationNafeza.Count > 0) // there is record for the house (Update house nafeza)
            {
                UpdateClause += $"ACID = '{ValidateACIDDTO.pACIDNumber}',";
                UpdateClause += $"ConsigneeVATNumber = '{ValidateACIDDTO.pConsigneeVATNumber}',";
                UpdateClause += $"ShipperVATNumber = '{ValidateACIDDTO.pShipperVATNumber}',";
                UpdateClause += $"NafezaRegistrationType = '{ValidateACIDDTO.pRegistrationType}',";
                UpdateClause += $"NafezaPickupCountryid = {ValidateACIDDTO.pPickupCountry},";
                UpdateClause += $"NafezaPickupCountryname = '{ValidateACIDDTO.pPickupCountryName}'";
                UpdateClause += $" where OperationID = {ValidateACIDDTO.pShipmentID}";



                checkExcpetion = CheckIfThereData.UpdateList(UpdateClause);

            }
            else // there is no record for the house  (insert house nafeza)
            {
                COperationNafeza cOperationNafeza = new COperationNafeza();
                CVarOperationNafeza cVarOperationNafeza = new CVarOperationNafeza();
                cVarOperationNafeza.ACID = ValidateACIDDTO.pACIDNumber;
                cVarOperationNafeza.ConsigneeVATNumber = ValidateACIDDTO.pConsigneeVATNumber;
                cVarOperationNafeza.ShipperVATNumber = ValidateACIDDTO.pShipperVATNumber;
                cVarOperationNafeza.NafezaRegistrationType = ValidateACIDDTO.pRegistrationType;
                cVarOperationNafeza.NafezaPickupCountryid = ValidateACIDDTO.pPickupCountry;
                cVarOperationNafeza.NafezaPickupCountryname = ValidateACIDDTO.pPickupCountryName;
                cVarOperationNafeza.operationID = ValidateACIDDTO.pShipmentID;

                cOperationNafeza.lstCVarOperationNafeza.Add(cVarOperationNafeza);
                checkExcpetion = cOperationNafeza.SaveMethod(cOperationNafeza.lstCVarOperationNafeza);
            }


            CCountries objCCountries = new CCountries();
            objCCountries.GetItem(ValidateACIDDTO.pPickupCountry);
            string AcidReturn = "";

            if (objCCountries.lstCVarCountries.Count == 1 && checkExcpetion == null)
            {
                try
                {
                    var response = ACID.GetACIDStat(ValidateACIDDTO.pACIDNumber, ValidateACIDDTO.pConsigneeVATNumber, ValidateACIDDTO.pShipperVATNumber, ValidateACIDDTO.pRegistrationType, objCCountries.lstCVarCountries[0].Code.ToString());
                    AcidReturn = response[0];

                    string LogACID = response[1];
                    var loggingEntity = new CTransactionsLog();
                    loggingEntity.lstCVarTransactionsLog.Add(new CVarTransactionsLog()
                    {
                        LogTableName = "OperationNafeza",
                        RecordID = ValidateACIDDTO.pShipmentID,
                        Log = LogACID,
                        OpertionCode = "0",
                        ParentCode = "0",
                        Code = "0",
                        ParentID = 0

                    });
                    var ex = loggingEntity.SaveMethod(loggingEntity.lstCVarTransactionsLog);

                } catch (Exception ex)
                {
                    return new object[]
                    {
                        false
                        ,"Data Saved But Error in Validating"
                    };
                }


            }

            if (checkExcpetion == null)
            {
                return new object[]
                {
                    true
                    ,AcidReturn
                };
            }

            return new object[]
            {
                false
                ,"Error Happened"
            };
        }

