        #region SetHouseDeliveryOrderPrintData
        [HttpPost]
        public object[] SetHouseDeliveryOrderPrintData([FromBody] HouseDeliveryOrderPrintData houseDeliveryOrderPrintData)
        {
            var checkException = new Exception();
            bool Status = true;
            string ExceptionMessage = "";
            COperations objCOperations = new COperations();
            COperations objCOperations2 = new COperations();

            objCOperations2.GetItem((long)houseDeliveryOrderPrintData.pShipmentID);

            int _RowCount = 0;
            CDefaults objCDefaults = new CDefaults();
            checkException = objCDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);
            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName != "MES")
            {
                if (objCOperations2.lstCVarOperations.Count == 1 && objCOperations2.lstCVarOperations[0].DOPrintedON != DateTime.Parse("01-01-1900"))
                {
                    return new object[]
                    {
                        ExceptionMessage,
                        Status
                    };
                }
            }

            string strUpdate = $" DORepresentative = N'{houseDeliveryOrderPrintData.pRepresentativeName}',DOPrintedON = '{DateTime.Now}',DeliveryCustomer = N'{houseDeliveryOrderPrintData.pDeliveryCustomer}' WHERE ID = {houseDeliveryOrderPrintData.pShipmentID}";
            checkException = objCOperations.UpdateList(strUpdate);

            if (checkException != null)
            {
                Status = false;
                ExceptionMessage = checkException.Message;
            }

            return new object[]
            {
                ExceptionMessage,
                Status
            };
        }
