        [HttpGet]
        public object[] FillHouseControls(Int64 pHouseID)
        {

            Exception checkException = null;
            int _RowCount = 0;

            CDefaults objCDefaults = new CDefaults();
            checkException = objCDefaults.GetListPaging(1, 1, "WHERE 1=1", "ID", out _RowCount);

            /**************************************Operation Details******************************************/
            COperations objCOperations = new COperations();
            if (pHouseID > 0) //this means the house already exists
                checkException = objCOperations.GetItem(pHouseID);

            /**************************************Salesmen Details******************************************/
            CUsers objCUsers = new CUsers();
            var CurrentUserID = WebSecurity.CurrentUserId;
            if (objCDefaults.lstCVarDefaults[0].ShowUserSalesmen == true)
                checkException = objCUsers.GetList(" Where IsNull(CustomerID , 0) = 0 AND IsNull( (SELECT COUNT(us.ID) FROM dbo.UserSalesmen AS us WHERE us.UserID = " + CurrentUserID + " AND us.SalesManID = dbo.Users.ID  ) , 0 ) > 0 ORDER BY Name");
            else
                checkException = objCUsers.GetList(" where IsNull(CustomerID , 0) = 0 AND 1 = 1 ORDER BY Name");

            var pUserList = objCUsers.lstCVarUsers.Select(s => new
            {
                ID = s.ID
                ,
                Name = s.Name
                ,
                IsSalesman = s.IsSalesman
            }).ToList();

            /**************************************Countries Details******************************************/
            CCountries objCCountries = new CCountries();
            checkException = objCCountries.GetListPaging(999999, 1, "WHERE 1=1", "Name", out _RowCount);
            CNoAccessQuoteAndOperStages objCNoAccessQuoteAndOperStages = new CNoAccessQuoteAndOperStages();
            if (objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF")
            {
                checkException = objCNoAccessQuoteAndOperStages.GetListPaging(99999, 1, "WHERE Name IN ('CANCELLED','OPEN','CLOSED','INVOICE','Booked','ARRIVED','Pending','Sailed')", "ID", out _RowCount);
            }
            else
            {
                checkException = objCNoAccessQuoteAndOperStages.GetListPaging(99999, 1, "WHERE Name IN ('CANCELLED','CLOSED','INVOICE','Booked')", "ID", out _RowCount);
            }
            var Status = objCNoAccessQuoteAndOperStages.lstCVarNoAccessQuoteAndOperStages.Select(s => new
            {
                ID = s.ID,
                Name = s.Name
            }).ToList();

            /**************************************Ports Details********************************************/

            CPorts objCPortOfPickup = new CPorts();
            CPorts objCPortOfPickupNEW = new CPorts();
            CPorts objCPortOfDestination = new CPorts();
            dynamic PortOfPickupNew;
            dynamic PortOfDestinationNew;
            if (pHouseID == 0)
            {
                checkException = objCPortOfPickup.GetList("WHERE 1=1");
                checkException = objCPortOfDestination.GetList("WHERE 1=1");
                PortOfPickupNew = objCPortOfPickup.lstCVarPorts.Select(p => new
                {
                    ID = p.ID,
                    Name = p.Name,
                    Code = p.Code
                }).ToList();
                PortOfDestinationNew = objCPortOfDestination.lstCVarPorts.Select(p => new
                {
                    ID = p.ID,
                    Name = p.Name,
                    Code = p.Code
                }).ToList();
            }
            else
            {
                PortOfPickupNew = null;
                PortOfDestinationNew = null;
                int PickupCountryID = 0;
                int PickupCountryIDUNF = 0;
                if (objCOperations.lstCVarOperations[0].PickupCityID != 0)
                {
                    CPorts objCPorts = new CPorts();
                    checkException = objCPorts.GetItem(objCOperations.lstCVarOperations[0].PickupCityID);
                    PickupCountryID = objCPorts.lstCVarPorts.Count > 0 ? objCPorts.lstCVarPorts[0].CountryID : 0;
                }
                if (objCOperations.lstCVarOperations[0].ATAPOLAlarmStatus != 0 && objCDefaults.lstCVarDefaults[0].UnEditableCompanyName == "UNF")
                {
                    CPorts objCPorts = new CPorts();
                    checkException = objCPorts.GetItem(objCOperations.lstCVarOperations[0].ATAPOLAlarmStatus);
                    PickupCountryIDUNF = objCPorts.lstCVarPorts.Count > 0 ? objCPorts.lstCVarPorts[0].CountryID : 0;
                }
                checkException = objCPortOfPickupNEW.GetList("WHERE CountryID=" + (PickupCountryIDUNF == 0 ? objCOperations.lstCVarOperations[0].ETAPOLAlarmStatus : PickupCountryIDUNF));
                checkException = objCPortOfPickup.GetList("WHERE CountryID=" + (PickupCountryID == 0 ? objCOperations.lstCVarOperations[0].POLCountryID : PickupCountryID));
                checkException = objCPortOfDestination.GetList("WHERE CountryID=" + (objCOperations.lstCVarOperations[0].DeliveryCountryID == 0 ? objCOperations.lstCVarOperations[0].PODCountryID : objCOperations.lstCVarOperations[0].DeliveryCountryID));
            }

            /**************************************Incoterms Details********************************************/

            CIncoterms objCIncoterms = new CIncoterms();
            checkException = objCIncoterms.GetListPaging(999999, 1, "WHERE 1=1", "Name", out _RowCount);

            /**************************************MoveTypes Details********************************************/

            CMoveTypes objCMoveTypes = new CMoveTypes();
            checkException = objCMoveTypes.GetListPaging(999999, 1, "WHERE 1=1", "Name", out _RowCount);

            /**************************************Customers Details********************************************/
            int pNotifyID = 0;
            int constNotify1OperationPartnerTypeID = 4;
            COperationPartners objCOperationPartners = new COperationPartners();
            checkException = objCOperationPartners.GetList("WHERE OperationID=" + pHouseID + " AND OperationPartnerTypeID=" + constNotify1OperationPartnerTypeID);
            if (objCOperationPartners.lstCVarOperationPartners.Count > 0)
                pNotifyID = objCOperationPartners.lstCVarOperationPartners[0].CustomerID;

            /**************************************Routing Details********************************************/

            int MainCarraigeRoutingTypeID = 30;
            CRoutings objCRoutings = new CRoutings();
            objCRoutings.GetListPaging(10, 1, "WHERE OperationID=" + pHouseID + " AND RoutingTypeID=" + MainCarraigeRoutingTypeID, "ID", out _RowCount);

            /**************************************FreightTypes Details********************************************/

            CNoAccessFreightTypes objCNoAccessFreightTypes = new CNoAccessFreightTypes();
            checkException = objCNoAccessFreightTypes.GetListPaging(999999, 1, "WHERE 1=1", "Name", out _RowCount);

            /**************************************Vessel Details********************************************/

            CVessels objCVessels = new CVessels();
            checkException = objCVessels.GetList("Where 1=1");
            var VesselsList = objCVessels.lstCVarVessels.Select(v => new
            {
                ID = v.ID,
                Name = v.Name
            }).ToList();

            /**************************************Operation Closed Details********************************************/

            int CancelledQuoteAndOperStageID = 110;
            bool pIsOperationClosed = false;
            if (objCOperations.lstCVarOperations.Count > 0)
            {
                pIsOperationClosed = (objCOperations.lstCVarOperations[0].CloseDate < DateTime.Now && objCOperations.lstCVarOperations[0].OperationStageID != CancelledQuoteAndOperStageID);//2nd condition coz with time closedate passes but the operation is still cancelled
            }

            /**************************************Packages Details********************************************/

            COperationContainersAndPackages objCOperationContainersAndPackages = new COperationContainersAndPackages();
            checkException = objCOperationContainersAndPackages.GetListPaging(10000, 1, "WHERE OperationID=" + pHouseID.ToString() + " OR ID IN (SELECT OperationContainersAndPackagesID FROM OperationContainersAndPackagesPlacedOn WHERE OperationID=" + pHouseID.ToString() + ")", "ID", out _RowCount);

            string consignee = "";
            string shipper = "";
            string notify = "";
            string consignee2 = "";
            string forwarder = "";

            if (pHouseID > 0)
            {
                CCustomers objCCustomers = new CCustomers();
                Exception e = objCCustomers.GetItem(objCOperations.lstCVarOperations[0].ConsigneeID);
                if (e == null && objCCustomers.lstCVarCustomers.Count == 1)
                    consignee = objCCustomers.lstCVarCustomers[0].Name;

                e = objCCustomers.GetItem(objCOperations.lstCVarOperations[0].ShipperID);
                if (e == null && objCCustomers.lstCVarCustomers.Count == 1)
                    shipper = objCCustomers.lstCVarCustomers[0].Name;

                e = objCCustomers.GetItem(objCOperations.lstCVarOperations[0].ConsigneeID2);
                if (e == null && objCCustomers.lstCVarCustomers.Count == 1)
                    consignee2 = objCCustomers.lstCVarCustomers[0].Name;

                e = objCCustomers.GetItem(objCOperations.lstCVarOperations[0].ForwarderId);
                if (e == null && objCCustomers.lstCVarCustomers.Count == 1)
                    forwarder = objCCustomers.lstCVarCustomers[0].Name;

                e = objCCustomers.GetItem(pNotifyID);
                if (e == null && objCCustomers.lstCVarCustomers.Count == 1)
                    notify = objCCustomers.lstCVarCustomers[0].Name;

            }

            string _ReturnedMessage = "";
            if (checkException != null)
            {
                _ReturnedMessage = checkException.Message;
            }


            var serializer = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
            return new object[]
            {
                pHouseID > 0 ? serializer.Serialize(objCOperations.lstCVarOperations[0]) : null //pData[0]
                , serializer.Serialize(pUserList) //pData[1]
                , serializer.Serialize(objCCountries.lstCVarCountries) //pData[2]
                , pHouseID > 0 ? serializer.Serialize(objCPortOfPickup.lstCVarPorts) : serializer.Serialize(PortOfPickupNew) //pData[3]
                , pHouseID > 0 ? serializer.Serialize(objCPortOfDestination.lstCVarPorts) : serializer.Serialize(PortOfDestinationNew) //pData[4]
                , serializer.Serialize(objCIncoterms.lstCVarIncoterms) //pData[5]
                , serializer.Serialize(objCMoveTypes.lstCVarMoveTypes) //pData[6]
                , pNotifyID //pData[7]
                , objCRoutings.lstCVarRoutings.Count > 0 ? serializer.Serialize(objCRoutings.lstCVarRoutings[0]) : null
                , serializer.Serialize(objCNoAccessFreightTypes.lstCVarNoAccessFreightTypes) //pData[9]
                , serializer.Serialize(VesselsList) //pData[10]
                , pIsOperationClosed //pData[11]
                , serializer.Serialize(objCOperationContainersAndPackages.lstCVarOperationContainersAndPackages) //pData[12]
                , _ReturnedMessage //pData[13]
                ,serializer.Serialize(Status) //pData[14]
                ,consignee
                ,shipper
                ,notify
                ,consignee2
                ,forwarder
                , pHouseID > 0 ? serializer.Serialize(objCPortOfPickupNEW.lstCVarPorts) : null
            };
        }

