                portOfPickup = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
  $"select ID,Code,Name from Ports WHERE 1=1 {(pIsAWB ? " AND IsAir=1 " : "")}"
  , typeof(CVarPorts)).Cast<CVarPorts>().ToList();
