            //"select ID,Name from Incoterms WHERE 1 = 1"
            //, typeof(CVarIncoterms)).Cast<CVarIncoterms>().ToList();

            //			var moveTypes = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
            //"select ID,Name from MoveTypes WHERE 1 = 1"
            //, typeof(CVarMoveTypes)).Cast<CVarMoveTypes>().ToList();

            //			var noAccessFreightTypes = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
            //"select ID,Name from NoAccessFreightTypes WHERE 1 = 1"
            //, typeof(CVarNoAccessFreightTypes)).Cast<CVarNoAccessFreightTypes>().ToList();

            //			string usersFilter = "where IsNull(CustomerID , 0) = 0 AND 1 = 1 ORDER BY Name";
            //			if (pShowUserSalesmen == true)
            //				usersFilter = $" Where IsNull(CustomerID , 0) = 0 AND IsNull( (SELECT COUNT(us.ID) FROM dbo.UserSalesmen AS us WHERE us.UserID = " + WebSecurity.CurrentUserId + " AND us.SalesManID = dbo.Users.ID  ) , 0 ) > 0 ORDER BY Name";

            //			var users = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
            //$"select ID,Name from Users {usersFilter}"
            //, typeof(CVarUsers)).Cast<CVarUsers>().ToList();


            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };

            return new
