                countries = serializer.Serialize(countries),
                vessels = serializer.Serialize(vessels),
                warehouses = serializer.Serialize(warehouses),
                ports = serializer.Serialize(ports),
                portOfDestination = serializer.Serialize(portOfDestinationNew),
                portOfPickup = serializer.Serialize(portOfPickupNew),
