        [HttpGet, HttpPost]
        public Object[] updatePlacedOnDetails(string pGrossWeight, string pVolume, string pID)
        {
            string _ReturnedMessage = "";
            string _UpdateClause = "";
            Exception checkException = null;
            CPlacedOnDetails cPlacedOnDetails = new CPlacedOnDetails();
            _UpdateClause = "";
            _UpdateClause += "  volume = " + (pVolume == "0" ? " NULL " : pVolume) + "\n";
            _UpdateClause += " , grossweight = " + (pGrossWeight == "0" ? " NULL " : pGrossWeight) + "\n";
            _UpdateClause += "WHERE ID=" + pID + "\n";
            checkException = cPlacedOnDetails.UpdateList(_UpdateClause);
            if (checkException != null)
                _ReturnedMessage = checkException.Message;
            return new object[] {
                _ReturnedMessage
            };
        }
