        [HttpGet]
        public object[] GetOperationPayablesAndReceivables(int pOperationID)
        {
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var OperationPayables = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "SELECT ID,ChargeTypeName,CurrencyCode,QuotationCost,CategoryID , IsCancelled,IsDeleted  FROM vwPayables WHERE OperationID=" + pOperationID
                , typeof(CVarvwPayables)).Cast<CVarvwPayables>().ToList();
            var OperationReceivables = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "SELECT ID,ChargeTypeName,CurrencyCode,SaleAmount,CategoryID ,IsCancelled,IsDeleted  FROM vwReceivables WHERE OperationID=" + pOperationID
                , typeof(CVarvwReceivables)).Cast<CVarvwReceivables>().ToList();
            var Categories = objCCustomizedDBCall.ExecuteQuery_ListOfObjects(
                "SELECT ID,Name FROM ChargeTypeGroup"
                , typeof(CVarChargeTypeGroup)).Cast<CVarChargeTypeGroup>().ToList();
            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new object[] {
                new JavaScriptSerializer().Serialize(OperationPayables), //pData[0]
                new JavaScriptSerializer().Serialize(OperationReceivables), //pData[1]
                new JavaScriptSerializer().Serialize(Categories) //pData[2]
            };
        }

        [HttpPost]
        public object[] UpdateOperationCharges([FromBody] UpdateOperationChargesModel Charges)
        {
            Exception checkException = null;
            bool _result = true;
            CPayables objCPayables = new CPayables();
            CReceivables objCReceivables = new CReceivables();
            Charges.pPayableCategories.ForEach(payable =>
            {
                if (checkException == null)
                    checkException = objCPayables.UpdateList($"CategoryID = {payable.pCategoryID} WHERE ID = {payable.pID}");
            });
            Charges.pReceivableCategories.ForEach(receivable =>
            {
                if (checkException == null)
                    objCReceivables.UpdateList($"CategoryID = {receivable.pCategoryID} WHERE ID = {receivable.pID}");
            });

            if (checkException != null)
                _result = false;

            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new object[] {
                _result
            };
        }

