        [HttpGet]
        public object[] CheckSalesmanReceivables(int pQuotationRouteID)
        {
            bool CanCreateOperation = true;
            string Salesman = "";
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var QueryResult = objCCustomizedDBCall.CallStringFunction($@"SELECT TOP 1 1 FROM Receivables R 
                JOIN Operations O ON O.ID = R.OperationID 
                AND O.QuotationRouteID IS NOT NULL 
                AND O.SalesmanID = (SELECT Q.SalesmanID FROM QuotationRoute QR JOIN Quotations Q ON Q.ID = QR.QuotationID WHERE QR.ID = {pQuotationRouteID}) 
                AND O.MasterOperationID IS NULL 
                WHERE R.IsDeleted = 0 AND ISNULL(R.InvoiceID,0) = 0
                AND O.OpenDate < DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)
                AND O.ID IN (select o2.ID from Operations o2
                where o2.BLType<>2 and (select count(*) from Receivables r3 where r3.OperationID=o2.ID)<>(select count(*) from Receivables r2 where r2.OperationID=o2.ID and r2.InvoiceID is null and r2.DraftInvoiceID is null) and (select count(*) from Receivables r2 where r2.OperationID=o2.ID and r2.InvoiceID is null and r2.DraftInvoiceID is null)<>0)
                "
            );

            if (QueryResult == "1")
            {
                CanCreateOperation = false;
                Salesman = objCCustomizedDBCall.CallStringFunction($@"SELECT Name FROM Salesmen S 
                JOIN Quotations Q ON Q.SalesmanID = S.ID 
                JOIN QuotationRoute QR ON QR.QuotationID = Q.ID");
            }


            var serializer = new JavaScriptSerializer() { MaxJsonLength = Int32.MaxValue };
            return new object[]
            {
                CanCreateOperation,
                Salesman
            };
        }

