        private Exception InsertAKSOperationTracking(Models.Operations.Operations.Generated.Old.CVarOperations pOperation)
        {
            if (pOperation == null || pOperation.ID == 0)
            {
                return new Exception("Operation Not Exist!");
            }

            COperationTracking objCOperationTracking = new COperationTracking();

            string whereClause = " where 1 = 1 ";
            switch (pOperation.DirectionType)
            {
                case 1: whereClause += " and IsImport = 1"; break;
                case 2: whereClause += " and IsExport = 1"; break;
                case 3: whereClause += " and IsDomestic = 1"; break;
            }
            switch (pOperation.TransportType)
            {
                case 1: whereClause += " and IsOcean = 1"; break;
                case 2: whereClause += " and IsAir = 1"; break;
                case 3: whereClause += " and IsInland = 1"; break;
            }
            whereClause += " AND Name IN ('INVOICING','PAYMENT ORDER','EXPENSE','DOCUMENT UPLOAD','ARRIVAL NOTICE')";
            var objCTrackingStage = new CTrackingStage();
            Exception checkException = objCTrackingStage.GetList(whereClause);

            var datetimeNow = DateTime.Now;

            foreach (var item in objCTrackingStage.lstCVarTrackingStage)
            {
                objCOperationTracking.lstCVarOperationTracking.Add(new CVarOperationTracking
                {
                    OperationID = pOperation.ID,
                    TrackingStageID = item.ID,
                    CreatorUserID = WebSecurity.CurrentUserId,
                    ModificatorUserID = WebSecurity.CurrentUserId,
                    CreationDate = datetimeNow,
                    ModificationDate = datetimeNow
                });
                Common.Common.ReplaceNull(objCOperationTracking.lstCVarOperationTracking[objCOperationTracking.lstCVarOperationTracking.Count - 1]);
            }
            if (objCOperationTracking.lstCVarOperationTracking.Count > 0)
                checkException = objCOperationTracking.SaveMethod(objCOperationTracking.lstCVarOperationTracking);
            return checkException;
        }

        private Exception LinkOperationToBooking(Models.Operations.Operations.Generated.Old.CVarOperations pOperation)
        {
            Exception e = null;

            CBookings objCBookings = new CBookings();
            e = objCBookings.UpdateList($"OperationID={pOperation.ID} WHERE BookingNumber='{pOperation.BookingNumber}'");
            if (e == null)
            {
                objCBookings.GetList($"WHERE BookingNumber='{pOperation.BookingNumber}'");
                if (objCBookings.lstCVarBookings.Count == 1)
                {
                    var booking = objCBookings.lstCVarBookings[0];
                    COperations objCOperations = new COperations();
                    objCOperations.UpdateList($"DOPrintedON='{booking.SLDate.ToString("yyyy-MM-dd hh:mm tt")}', BusinessUnit='{booking.Hazmat.ToUpper()}', ReleaseDate = '{booking.ValidatedTitlesDate.ToString("yyyy-MM-dd")}' WHERE ID={pOperation.ID}");
                }
            }

            return e;
        }
        [HttpGet]
        public bool checkCustomerIsTracked(int customerID, bool isImport, bool isExport)
        {
            bool isTracked = false;
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var QueryResult = objCCustomizedDBCall.CallStringFunction($@"select top 1 1 from ShipsGoCustomers where CustomerID={customerID} and cast(GETDATE() as date) between FromDate and ToDate  {(isImport ? "and IsImport=1" : "")} {(isExport ? "and IsExport=1" : "")}
                "
            );
            if (QueryResult == "1")
            {
                isTracked = true;
            }
            return isTracked;
        }

        [HttpGet, HttpPost]
        public object UploadOperationByExcel()
        {
            Exception exception = null;
            StringBuilder msg = new StringBuilder();

            try
            {
                var fileSavePath = "";

                if (HttpContext.Current.Request.Files.AllKeys.Any())
                {
                    // Get the uploaded image from the Files collection
                    var httpPostedFile = HttpContext.Current.Request.Files[0];
                    //HttpPostedFileBase = HttpContext.Current.Request.Files[0];

                    if (httpPostedFile != null)
                    {
                        // Validate the uploaded image(optional)

                        // Get the complete file path
                        fileSavePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/uploads"), httpPostedFile.FileName);

                        // Save the uploaded file to "UploadedFiles" folder
                        //httpPostedFile.SaveAs(fileSavePath);
                        httpPostedFile.SaveAs(System.IO.Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/uploads"), httpPostedFile.FileName));

                        Stream stream = httpPostedFile.InputStream;
                        IExcelDataReader reader = null;
                        if (httpPostedFile.FileName.EndsWith(".xls"))
                        {
                            reader = ExcelReaderFactory.CreateBinaryReader(stream);
                        }
                        else if (httpPostedFile.FileName.EndsWith(".xlsx"))
                        {
                            reader = ExcelReaderFactory.CreateOpenXmlReader(stream);
                        }
                        else
                        {
                            ModelState.AddModelError("File", "This file format is not supported");
                        }
                        DataSet result = reader.AsDataSet(new ExcelDataSetConfiguration()
                        {
                            ConfigureDataTable = (_) => new ExcelDataTableConfiguration()
                            {
                                UseHeaderRow = true
                            }
                        });

                        var defDate = new DateTime(1900, 1, 1);
                        var defDateStr = new DateTime(1900, 1, 1).ToString("dd/MM/yyyy");
                        var now = DateTime.Now;
                        var nowStr = DateTime.ParseExact(now.ToString("dd/MM/yyyy hh.mm.ss.fff"), "dd/MM/yyyy hh.mm.ss.fff", CultureInfo.InvariantCulture);
                        var nowDateStr = DateTime.ParseExact(now.ToString("dd/MM/yyyy") + " 00.00.00.000", "dd/MM/yyyy hh.mm.ss.fff", CultureInfo.InvariantCulture);

                        CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();

                        List<OperationExcel> Operations = new List<OperationExcel>();
                        OperationExcel Operation;

                        var IsValid = true;
                        var line = 0;
                        foreach (DataRow row in result.Tables[0].Rows)
                        {
                            Operation = new OperationExcel
                            {
                                Branch = row["Branch"] == DBNull.Value ? "" : Convert.ToString(row["Branch"]),
                                OpenDate = row["OpenDate"] == DBNull.Value ? "" : Convert.ToString(row["OpenDate"]),
                                BLType = row["BLType"] == DBNull.Value ? "" : Convert.ToString(row["BLType"]),
                                Direction = row["Direction"] == DBNull.Value ? "" : Convert.ToString(row["Direction"]),
                                TransportType = row["TransportType"] == DBNull.Value ? "" : Convert.ToString(row["TransportType"]),
                                ShipType = row["ShipType"] == DBNull.Value ? "" : Convert.ToString(row["ShipType"]),
                                ServiceType = row["ServiceType"] == DBNull.Value ? "" : Convert.ToString(row["ServiceType"]),
                                Salesman = row["Salesman"] == DBNull.Value ? "" : Convert.ToString(row["Salesman"]),
                                Shipper = row["Shipper"] == DBNull.Value ? "" : Convert.ToString(row["Shipper"]),
                                Consignee = row["Consignee"] == DBNull.Value ? "" : Convert.ToString(row["Consignee"]),
                                Line = row["Line"] == DBNull.Value ? "" : Convert.ToString(row["Line"]),
                                POLCountry = row["POLCountry"] == DBNull.Value ? "" : Convert.ToString(row["POLCountry"]),
                                POL = row["POL"] == DBNull.Value ? "" : Convert.ToString(row["POL"]),
                                PODCountry = row["PODCountry"] == DBNull.Value ? "" : Convert.ToString(row["PODCountry"]),
                                POD = row["POD"] == DBNull.Value ? "" : Convert.ToString(row["POD"]),
                                MasterBL = row["MasterBL"] == DBNull.Value ? "" : Convert.ToString(row["MasterBL"]),
                                ContainerType = row["ContainerType"] == DBNull.Value ? "" : Convert.ToString(row["ContainerType"]),
                                Qty = row["Qty "] == DBNull.Value ? "" : Convert.ToString(row["Qty "]),
                            };
                            #region Required
                            if (string.IsNullOrWhiteSpace(Operation.Branch))
                            {
                                msg.AppendLine($"Branch is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.OpenDate))
                            {
                                msg.AppendLine($"OpenDate is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.BLType))
                            {
                                msg.AppendLine($"BLType is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.Direction))
                            {
                                msg.AppendLine($"Direction is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.TransportType))
                            {
                                msg.AppendLine($"TransportType is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (Operation.TransportType.ToLower() != "air" && string.IsNullOrWhiteSpace(Operation.ShipType))
                            {
                                msg.AppendLine($"ShipType is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.ServiceType))
                            {
                                msg.AppendLine($"ServiceType is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.Salesman))
                            {
                                msg.AppendLine($"Salesman is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.Shipper) && Operation.Direction.ToLower() == "export")
                            {
                                msg.AppendLine($"Shipper is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.Consignee) && Operation.Direction.ToLower() == "import")
                            {
                                msg.AppendLine($"Consignee is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.Line))
                            {
                                msg.AppendLine($"Line is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.POLCountry))
                            {
                                msg.AppendLine($"POLCountry is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.POL))
                            {
                                msg.AppendLine($"POL is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.PODCountry))
                            {
                                msg.AppendLine($"PODCountry is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.POD))
                            {
                                msg.AppendLine($"POD is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            if (string.IsNullOrWhiteSpace(Operation.MasterBL))
                            {
                                msg.AppendLine($"MasterBL is required\nline:{line}");
                                IsValid = false;
                                break;
                            }
                            #endregion
                            #region Fix
                            if (Operation.OpenDate.Length > 0)
                            {
                                if (Operation.OpenDate.Length < 10)
                                {
                                    msg.AppendLine($"OpenDate format should be \n (dd/MM/yyyy or dd-MM-yyyy)");
                                    IsValid = false;
                                    break;
                                }
                                else
                                    Operation.OpenDate = Operation.OpenDate.Substring(0, 10);
                            }
                            Operation.OpenDate = Operation.OpenDate.Replace('-', '/');

                            if (Operation.BLType.ToLower() == "direct")
                            {
                                if (Operation.TransportType.ToLower() == "ocean" && !new string[] { "fcl", "lcl", "flexi", "tank", "bulk" }.Contains(Operation.ShipType.ToLower()))
                                {
                                    msg.AppendLine($"ShipType must be fcl,lcl,flexi,tank,bulk\nline:{line}");
                                    IsValid = false;
                                    break;
                                }
                                if (Operation.TransportType.ToLower() == "inland" && !new string[] { "ftl", "ltl", "flexi", "tank", "bulk" }.Contains(Operation.ShipType.ToLower()))
                                {
                                    msg.AppendLine($"ShipType must be ftl,ltl,flexi,tank,bulk\nline:{line}");
                                    IsValid = false;
                                    break;
                                }
                            }
                            else if (Operation.BLType.ToLower() == "master")
                            {
                                if (Operation.TransportType.ToLower() == "ocean" && !new string[] { "fcl", "lcl", "flexi", "tank", "bulk", "consolidation" }.Contains(Operation.ShipType.ToLower()))
                                {
                                    msg.AppendLine($"ShipType must be fcl,lcl,flexi,tank,bulk,consolidation\nline:{line}");
                                    IsValid = false;
                                    break;
                                }
                                if (Operation.TransportType.ToLower() == "inland" && !new string[] { "ftl", "ltl", "flexi", "tank", "bulk", "consolidation" }.Contains(Operation.ShipType.ToLower()))
                                {
                                    msg.AppendLine($"ShipType must be ftl,ltl,flexi,tank,bulk,consolidation\nline:{line}");
                                    IsValid = false;
                                    break;
                                }
                            }
                            #endregion

                            Operations.Add(Operation);
                            line++;
                        }

                        if (Operations.Count == 0)
                        {
                            msg.AppendLine($"No data");
                            IsValid = false;
                        }
                        if (IsValid)
                        {
                            #region GetIDs
                            var BlTypes = new List<SelectListOption> { new SelectListOption { ID = 1, Name = "direct", LocalName = "fa-indent", Code = "direct-icon-style" }, new SelectListOption { ID = 2, Name = "master" } };

                            var directionsNames = "N'" + string.Join("',N'", Operations.Select(a => a.Direction).Distinct()) + "'";
