                            var Branches = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"select ID, Name from Branches where Name in ({branchesNames})", typeof(SelectListOption)).Cast<SelectListOption>().ToList();

                            var servsNames = "N'" + string.Join("',N'", Operations.Select(a => a.ServiceType).Distinct()) + "'";
