                            var salesmenNames = "N'" + string.Join("',N'", Operations.Select(a => a.Salesman).Distinct()) + "'";
                            var Salesmen = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"select ID, Name from Users where Name in ({salesmenNames}) and IsSalesman=1", typeof(SelectListOption)).Cast<SelectListOption>().ToList();

                            var customersNames = "N'" + string.Join("',N'", Operations.Select(a => a.Shipper).Distinct()) + "'" + "," + "N'" + string.Join("',N'", Operations.Select(a => a.Consignee).Distinct()) + "'"; ;
                            var Customers = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"select ID, Name from Customers where Name in ({customersNames})", typeof(SelectListOption)).Cast<SelectListOption>().ToList();

