                            var countriesNames = "N'" + string.Join("',N'", Operations.Select(a => a.POLCountry).Distinct()) + "'" + "," + "N'" + string.Join("',N'", Operations.Select(a => a.PODCountry).Distinct()) + "'";
                            var Countries = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"select ID, Name from Countries where Name in ({countriesNames})", typeof(SelectListOption)).Cast<SelectListOption>().ToList();

                            var portsNames = "N'" + string.Join("',N'", Operations.Select(a => a.POL).Distinct()) + "'" + "," + "N'" + string.Join("',N'", Operations.Select(a => a.POD).Distinct()) + "'";
                            var Ports = objCCustomizedDBCall.ExecuteQuery_ListOfObjects($"select ID, Name from Ports where Name in ({portsNames})", typeof(SelectListOption)).Cast<SelectListOption>().ToList();
                            #endregion

                            #region Code
                            Exception chkEx;
                            CBranches objCBranches = new CBranches();
                            CCustomers objCCustomers = new CCustomers();
                            CUsers objCUsers = new CUsers();
                            CShippingLines objCShippingLines = new CShippingLines();
                            CMoveTypes objCMoveTypes = new CMoveTypes();
                            CCountries objCCountries = new CCountries();
                            CPorts objCPorts = new CPorts();
                            foreach (var op in Operations)
                            {
                                op.BLTypeID = (int)BlTypes.Find(a => a.Name.ToLower() == op.BLType.ToLower()).ID;
                                op.BLTypeIconName = BlTypes.Find(a => a.Name.ToLower() == op.BLType.ToLower()).LocalName;
