                                        pCloseDate = defDate,
                                        pCutOffDate = defDateStr,
                                        pBLDate = defDateStr,
                                        pReleaseDate = defDateStr,
                                        pExpectedDeparture = defDateStr,
                                        pExpectedArrival = defDateStr,
                                    });
                                    Common.Common.ReplaceNull(OpsData[OpsData.Count - 1], "0");
                                    OpResult = Insert(OpsData[OpsData.Count - 1]);
