                }
            }
            catch (Exception ex)
            {
                exception = ex;
                msg.AppendLine($"\n{ex.Message}\n");
            }

            return new { IsUploaded = msg.Length == 0 && exception == null, Msg = msg.ToString(), Exception = exception };
        }
        [HttpGet]
        public bool checkHouseNumber(string HouseNumber, string pShipmentID)
        {
            bool Exist = false;
            CCustomizedDBCall objCCustomizedDBCall = new CCustomizedDBCall();
            var Countid = objCCustomizedDBCall.CallStringFunction("select id from operations where HouseNumber='"+HouseNumber + "'");
            if (Countid != "")
            {
                if(Countid != pShipmentID && pShipmentID != "0" )
                Exist = true;
            }
            return Exist;
        }
    }

