    public static class ACID
    {
        public static string[] GetACIDStat(string ACIDNumber, string ConsigneeTaxID, string ShipperRegID, string RegType, string CountryCode)
        {
            string msg = "No Token";
            string fullResponse = "";
            string TokenStr = GetToken();
            if (RegType == "TaxNumber")
            {
                RegType = "1";
            } else if (RegType == "RegistrationNumber")
            {
                RegType = "0";
            }
            if (TokenStr != "")
            {
                string uuid = Guid.NewGuid().ToString() + "\"";
                RestClient client = new RestClient("https://eservices.nafeza.gov.eg/publicGW/api/documents/VerifyACIDs");
                client.Timeout = -1;
                var request = new RestRequest(Method.POST);
                request.AddHeader("Authorization", "Bearer " + TokenStr);
                request.AddHeader("Content-Type", "application/json");
                var body = @"{  " + "\n" +
                @"  ""RequestID"": """ + uuid + "," + "\n" +
                @"  ""ACIDsInfoCollection"": [" + "\n" +
                @"    {" + "\n" +
                @"      ""ACIDNumber"": """ + ACIDNumber + "\"," + "\n" +
                @"      ""EgyptianImporterVATNumber"": """ + ConsigneeTaxID + "\"," + "\n" +
                @"      ""ExporterRegisterationCountryCode"": """ + CountryCode + "\"," + "\n" +
                @"      ""ExporterRegisterationNumberTypeCode"": """ + "0" + RegType + "\"," + "\n" +
                @"      ""ExporterRegisterationNumber"": """ + ShipperRegID + "" + "\"\n" +
                @"    }" + "\n" +
                @"  ]" + "\n" +
                @"}";

                request.AddParameter("application/json", body, RestSharp.ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);

                fullResponse = response.Content.ToString();

                var objects = JArray.Parse("[" + response.Content.ToString() + "]");

                #region Get Stat
                foreach (JObject root in objects)
                {
                    msg = "ACID is ";
                    if (root.Count == 1)
                    {
                        msg = root["Message"].ToString();
                    }
                    else
                    {
                        foreach (KeyValuePair<String, JToken> app in (JObject)root["VerifyACIDResponseCollection"][0])
                        {
                            if (app.Key == "IsValid")
                            {
                                msg = msg + (app.Value.ToString().ToLower() == "true" ? "Valid " : "InValid ");
                            }
                            else if (app.Key == "ResponseMessage")
                            {
                                if (app.Value.ToString().Trim() != "")
                                {
                                    msg = msg + app.Value.ToString().Trim();
                                }
                            }
                            else if (app.Key == "ExpiryDate")
                            {
                                if (app.Value.ToString().Trim() != "")
                                {
                                    DateTime d = (DateTime)app.Value;
                                    msg = msg + "And Expiry Date is " + d.ToString("dd/MM/yyyy hh.mm.ss.fff");
                                }
                                break;
                            }
                        }

                    }
                }
                #endregion
            }
            return new string[]
            {
                msg
                ,fullResponse
            };
        }
        public static string GetToken()
        {
            string Token = "";
            ServicePointManager.Expect100Continue = true;
            ServicePointManager.DefaultConnectionLimit = 9999;
            ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072;
            var client = new RestClient("https://eservices.nafeza.gov.eg/publicGW/identity/token");
            client.Timeout = -1;
            var request = new RestRequest(Method.POST);
            request.AddHeader("Content-Type", "application/Json");
            request.AddParameter("grant_type", "client_credentials");
            request.AddParameter("scope", "aci.verify_before_shipment");
            request.AddParameter("client_id", "BB9360E41EE0FB12D574DEE203D8F1C4");
            request.AddParameter("client_secret", "mvJs5W7Yg+357Z1uJ/S/TeTe37+Ael/fb6NyQNYNcsU=");
            IRestResponse response = client.Execute(request);
            var objects = JArray.Parse("[" + response.Content.ToString() + "]");
            if (objects.Count > 0)
            {
                Token = ((JObject)objects[0]).GetValue("access_token").ToString();
            }
            return Token;

        }
    }
